  (0, '#e9f3cf', '/tin/bg-bc-bia.webp', '[{"id":"i1","type":"image","x":354,"y":74,"w":92,"h":92,"rotation":0,"src":"/brand/emblem.webp","radius":0,"opacity":1,"fit":"contain","borderWidth":0,"borderColor":"#c8a227"},{"id":"t2","type":"text","x":60,"y":184,"w":680,"rotation":0,"content":"UỶ BAN MẶT TRẬN TỔ QUỐC VIỆT NAM","fontSize":21,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#2f7d32","bold":true,"italic":false,"align":"center","lineHeight":1.3},{"id":"t3","type":"text","x":60,"y":214,"w":680,"rotation":0,"content":"PHƯỜNG YÊN NGHĨA","fontSize":27,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#2f7d32","bold":true,"italic":false,"align":"center","lineHeight":1.3},{"id":"t4","type":"text","x":60,"y":274,"w":680,"rotation":0,"content":"BÁO CÁO","fontSize":58,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.15},{"id":"t5","type":"text","x":60,"y":356,"w":680,"rotation":0,"content":"Kết quả công tác Mặt trận, các tổ chức chính trị - xã hội\n06 tháng đầu năm; phong trào “Dân vận khéo”\nvà nhiệm vụ trọng tâm 06 tháng cuối năm 2026","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#1f4d20","bold":true,"italic":false,"align":"center","lineHeight":1.5},{"id":"i6","type":"image","x":60,"y":490,"w":206,"h":143,"rotation":0,"src":"/tin/giay-khen.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#2f7d32"},{"id":"i7","type":"image","x":297,"y":490,"w":206,"h":143,"rotation":0,"src":"/tin/khen/bang-khen-bau-cu.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#2f7d32"},{"id":"i8","type":"image","x":534,"y":490,"w":206,"h":143,"rotation":0,"src":"/tin/khen/gk-nhap-ngu.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#2f7d32"},{"id":"t9","type":"text","x":60,"y":648,"w":680,"rotation":0,"content":"Giấy khen, Bằng khen tặng Uỷ ban MTTQ Việt Nam phường và các tổ chức thành viên","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"center","lineHeight":1.4},{"id":"i10","type":"image","x":185,"y":692,"w":430,"h":323,"rotation":0,"src":"/tin/trao-quyet-dinh-2.webp","radius":8,"opacity":1,"fit":"contain","borderWidth":3,"borderColor":"#2f7d32"},{"id":"t11","type":"text","x":60,"y":1030,"w":680,"rotation":0,"content":"Yên Nghĩa, tháng 8 năm 2026","fontSize":20,"fontFamily":"\"Times New Roman\", Times, serif","color":"#1f4d20","bold":false,"italic":true,"align":"center","lineHeight":1.4}]'),
  (1, '#e9f3cf', '/tin/bg-bc-bia.webp', '[{"id":"t12","type":"text","x":60,"y":150,"w":680,"rotation":0,"content":"UỶ BAN MẶT TRẬN TỔ QUỐC PHƯỜNG YÊN NGHĨA","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t13","type":"text","x":60,"y":196,"w":680,"rotation":0,"content":"- - - - - - - - - - - - - - - - -","fontSize":20,"fontFamily":"\"Times New Roman\", Times, serif","color":"#2f7d32","bold":false,"italic":false,"align":"center","lineHeight":1.3},{"id":"i14","type":"image","x":300,"y":300,"w":200,"h":200,"rotation":0,"src":"/brand/emblem.webp","radius":0,"opacity":1,"fit":"contain","borderWidth":0,"borderColor":"#c8a227"},{"id":"t15","type":"text","x":60,"y":594,"w":680,"rotation":0,"content":"BÁO CÁO","fontSize":46,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.2},{"id":"t16","type":"text","x":60,"y":672,"w":680,"rotation":0,"content":"Kết quả công tác Mặt trận, các tổ chức chính trị - xã hội\n06 tháng đầu năm; phong trào “Dân vận khéo”\nvà nhiệm vụ trọng tâm 06 tháng cuối năm 2026","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.6},{"id":"t17","type":"text","x":60,"y":1002,"w":680,"rotation":0,"content":"Yên Nghĩa, tháng 8 năm 2026","fontSize":21,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":true,"align":"center","lineHeight":1.4}]'),
  (2, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t18","type":"text","x":60,"y":96,"w":300,"rotation":0,"content":"UỶ BAN MTTQ VIỆT NAM PHƯỜNG YÊN NGHĨA","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t19","type":"text","x":60,"y":149,"w":300,"rotation":0,"content":"BAN THƯỜNG TRỰC","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t20","type":"text","x":60,"y":181,"w":300,"rotation":0,"content":"Số:        /BC-MTTQ-BTT","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.35},{"id":"t21","type":"text","x":384,"y":96,"w":356,"rotation":0,"content":"CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t22","type":"text","x":384,"y":149,"w":356,"rotation":0,"content":"Độc lập - Tự do - Hạnh phúc","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":true,"italic":false,"align":"center","lineHeight":1.35},{"id":"t23","type":"text","x":384,"y":181,"w":356,"rotation":0,"content":"Yên Nghĩa, ngày 04 tháng 8 năm 2026","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":true,"align":"center","lineHeight":1.35},{"id":"t24","type":"text","x":60,"y":207,"w":680,"rotation":0,"content":"BÁO CÁO","fontSize":34,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.2},{"id":"t25","type":"text","x":60,"y":272,"w":680,"rotation":0,"content":"Kết quả công tác Mặt trận, các tổ chức chính trị - xã hội 06 tháng đầu năm; phong trào “Dân vận khéo” và nhiệm vụ trọng tâm 06 tháng cuối năm 2026","fontSize":23,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"center","lineHeight":1.5},{"id":"t26","type":"text","x":60,"y":398,"w":680,"rotation":0,"content":"Thực hiện Công văn số 295-CV/ĐU ngày 29/7/2026 của Ban Thường vụ Đảng ủy phường Yên Nghĩa về làm việc với Ủy ban Mặt trận Tổ quốc Việt Nam và các tổ chức chính trị - xã hội phường để báo cáo kết quả công tác Mặt trận, các tổ chức chính trị - xã hội 6 tháng đầu năm, phong trào “Dân vận khéo” và nhiệm vụ trọng tâm 6 tháng cuối năm 2026, Ban Thường trực Ủy ban MTTQ Việt Nam phường Yên Nghĩa báo cáo như sau:","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t27","type":"text","x":60,"y":621,"w":680,"rotation":0,"content":"I. KẾT QUẢ THỰC HIỆN NHIỆM VỤ 6 THÁNG ĐẦU NĂM 2026","fontSize":27,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.3},{"id":"t28","type":"text","x":60,"y":703,"w":680,"rotation":0,"content":"1. Công tác lãnh đạo, chỉ đạo và tổ chức thực hiện","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t29","type":"text","x":60,"y":745,"w":680,"rotation":0,"content":"Bám sát Nghị quyết của Đảng bộ phường và các văn bản chỉ đạo của Ban Thường trực Ủy ban MTTQ Việt Nam Thành phố, ngay từ đầu năm Ban Thường trực Ủy ban MTTQ Việt Nam phường đã xây dựng và triển khai Chương trình công tác phối hợp và thống nhất hành động năm 2026;","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (3, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t30","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"cụ thể hóa thành các kế hoạch, hướng dẫn chuyên đề và phân công rõ trách nhiệm cho từng đồng chí Thường trực, chuyên viên và các tổ chức chính trị - xã hội.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t31","type":"text","x":60,"y":214,"w":680,"rotation":0,"content":"Trong 6 tháng đầu năm 2026, hệ thống Mặt trận phường đã ban hành 367 văn bản chỉ đạo, hướng dẫn, triển khai thực hiện nhiệm vụ; tổ chức các hội nghị học tập, quán triệt, triển khai Nghị quyết số 02-NQ/TW ngày 17/3/2026 của Bộ Chính trị về “Xây dựng và phát triển Thủ đô Hà Nội trong kỷ nguyên mới”, Luật Thủ đô (sửa đổi), Nghị quyết số 57-NQ/TW của Bộ Chính trị và các văn bản chỉ đạo về công tác bầu cử đại biểu Quốc hội khóa XVI, đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t32","type":"text","x":60,"y":472,"w":680,"rotation":0,"content":"* Kết quả thực hiện các nhiệm vụ do Đảng ủy, Ban Thường vụ, Thường trực Đảng ủy giao:","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":true,"italic":false,"align":"left","lineHeight":1.45},{"id":"t33","type":"text","x":60,"y":544,"w":680,"rotation":0,"content":"- Nhiệm vụ đã hoàn thành: Tổ chức thành công công tác Mặt trận tham gia cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031; chăm lo an sinh xã hội, tổ chức các hoạt động Mừng Đảng - Mừng Xuân Bính Ngọ 2026; tổ chức Ngày hội Đại đoàn kết toàn dân tộc và Hội nghị đại biểu Nhân dân bàn việc xây dựng đời sống văn hóa ở cơ sở; hoàn thành chương trình giám sát, phản biện xã hội 6 tháng đầu năm; vận động Quỹ “Vì biển, đảo Việt Nam” năm 2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t34","type":"text","x":60,"y":791,"w":680,"rotation":0,"content":"- Nhiệm vụ đang thực hiện: Kiện toàn tổ chức bộ máy Mặt trận ở khu dân cư sau sắp xếp đơn vị hành chính và sáp nhập tổ dân phố (từ 38 tổ dân phố còn 15 tổ dân phố);","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (4, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t35","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"kiện toàn Ban Công tác Mặt trận, Ban Thanh tra nhân dân, Ban Giám sát đầu tư của cộng đồng theo cơ cấu tổ chức mới; triển khai Kế hoạch phối hợp số 20/KHPH-UBND-UBMTTQ ngày 08/5/2026 về bầu thành viên Ban Giám sát đầu tư của cộng đồng đối với các chương trình, dự án đầu tư công trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t36","type":"text","x":60,"y":274,"w":680,"rotation":0,"content":"- Nhiệm vụ còn chậm tiến độ: Ban Thanh tra nhân dân phường chưa ban hành Kế hoạch hoạt động kiểm tra, giám sát năm 2026. Nguyên nhân chủ yếu do 6 tháng đầu năm tập trung cao độ cho công tác bầu cử và việc sắp xếp, kiện toàn tổ chức ở tổ dân phố; Ban Thường trực sẽ chỉ đạo hoàn thành, ban hành trong tháng 7/2026 và tổ chức cuộc giám sát chuyên đề đầu tiên trong Quý III/2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t37","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"2. Công tác tuyên truyền, vận động; nắm tình hình Nhân dân, đoàn viên, hội viên","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t38","type":"text","x":60,"y":562,"w":680,"rotation":0,"content":"2.1. Tình hình tư tưởng, tâm tư, nguyện vọng và dư luận xã hội","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t39","type":"text","x":60,"y":601,"w":680,"rotation":0,"content":"Trong 6 tháng đầu năm 2026, tình hình an ninh chính trị, trật tự xã hội và Nhân dân trên địa bàn phường nhìn chung ổn định; cán bộ, đảng viên và Nhân dân tin tưởng vào sự lãnh đạo của Đảng, Nhà nước và Thành phố, thể hiện sự quan tâm, kỳ vọng lớn đối với các chủ trương, chính sách mới được triển khai.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t40","type":"text","x":60,"y":789,"w":680,"rotation":0,"content":"Dư luận Nhân dân đánh giá cao chỉ đạo của Đảng, Nhà nước, Thành phố và của phường về việc bảo đảm cho Nhân dân đón Tết Nguyên đán Bính Ngọ 2026 vui tươi, an toàn, tiết kiệm.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (5, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t41","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nhân dân đặc biệt quan tâm, đồng tình và kỳ vọng lớn đối với việc Trung ương xem xét sửa đổi Nghị quyết số 15-NQ/TW, sửa đổi Luật Thủ đô gắn với Quy hoạch tổng thể Thủ đô tầm nhìn 100 năm; đánh giá cao chủ trương xây dựng các cơ chế, chính sách đặc thù tạo nền tảng vượt trội để xây dựng và phát triển Thủ đô. Việc khắc phục 5 “điểm nghẽn” được Thành phố triển khai quyết liệt, huy động sự vào cuộc của cả hệ thống chính trị, được dư luận đồng tình; nhiều vấn đề tồn tại kéo dài đã từng bước được xử lý.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t42","type":"text","x":60,"y":354,"w":680,"rotation":0,"content":"Nhân dân đánh giá cao kết quả Kỳ họp thứ nhất Quốc hội khóa XVI, Kỳ họp thứ Hai HĐND Thành phố và công tác kiện toàn nhân sự lãnh đạo HĐND, UBND nhiệm kỳ 2026 - 2031 sau bầu cử; đánh giá cao các hoạt động đối ngoại của lãnh đạo Đảng, Nhà nước, góp phần nâng cao vị thế quốc tế của Việt Nam.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t43","type":"text","x":60,"y":542,"w":680,"rotation":0,"content":"Bên cạnh đó, Nhân dân còn nhiều ý kiến, kiến nghị tập trung vào công tác bồi thường, hỗ trợ, giải phóng mặt bằng các dự án trọng điểm (đường Vành đai 4, mở rộng Quốc lộ 6, cải tạo mở rộng đường Đê Tả Đáy); công tác quản lý đất đai, trật tự đô thị, vệ sinh môi trường; chế độ, chính sách đối với cán bộ cơ sở và việc ổn định sinh hoạt cộng đồng sau sáp nhập tổ dân phố.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t44","type":"text","x":60,"y":730,"w":680,"rotation":0,"content":"2.2. Kết quả tuyên truyền, vận động","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t45","type":"text","x":60,"y":769,"w":680,"rotation":0,"content":"Công tác tuyên truyền được tăng cường với nhiều hình thức phong phú, bám sát nhiệm vụ chính trị của địa phương, tập trung vào: các nghị quyết Đại hội Đảng, Đại hội MTTQ Việt Nam các cấp nhiệm kỳ 2025 - 2030 và Đại hội đại biểu toàn quốc MTTQ Việt Nam lần thứ XI nhiệm kỳ 2026 -","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (6, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t46","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"2031; công tác bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031; các phong trào thi đua yêu nước, các cuộc vận động; nhiệm vụ phát triển kinh tế - xã hội; công tác giải phóng mặt bằng, tham gia tháo gỡ các \"điểm nghẽn\" của Thành phố; chuyển đổi số, khoa học, công nghệ và đổi mới sáng tạo.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t47","type":"text","x":60,"y":284,"w":680,"rotation":0,"content":"Việc quán triệt, tuyên truyền Nghị quyết số 02-NQ/TW ngày 17/3/2026 của Bộ Chính trị về xây dựng và phát triển Thủ đô Hà Nội trong kỷ nguyên mới và Nghị quyết số 57-NQ/TW của Bộ Chính trị về đột phá phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia được triển khai đồng bộ, gắn chặt với các nhiệm vụ chính trị của phường. Ủy ban MTTQ Việt Nam và các tổ chức chính trị - xã hội đã đổi mới nội dung, phương thức tuyên truyền theo hướng thiết thực, dễ tiếp cận; phát huy hiệu quả hệ thống truyền thanh cơ sở, các hội nghị tuyên truyền, sinh hoạt chi hội, chi đoàn, Ban Công tác Mặt trận, đồng thời tăng cường ứng dụng nền tảng số, mạng xã hội và Fanpage trong công tác thông tin, tuyên truyền, vận động. Qua đó, góp phần nâng cao nhận thức, tạo sự thống nhất về tư tưởng và hành động trong cán bộ, đoàn viên, hội viên và các tầng lớp Nhân dân đối với các chủ trương lớn của Đảng; khơi dậy tinh thần đổi mới, trách nhiệm tham gia chuyển đổi số, xây dựng chính quyền số, xã hội số, công dân số; củng cố niềm tin của Nhân dân đối với sự lãnh đạo của Đảng, sự quản lý, điều hành của chính quyền và quyết tâm xây dựng Thủ đô Hà Nội văn hiến - văn minh - hiện đại trong giai đoạn phát triển mới.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (7, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t48","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Tuyên truyền, vận động cán bộ, đoàn viên, hội viên tham gia Cuộc thi chính luận \"Bảo vệ nền tảng tư tưởng của Đảng trong tình hình mới\" lần thứ sáu với trên 100 bài dự thi; gửi 02 bài chất lượng về Ủy ban MTTQ Việt Nam Thành phố, 06 bài về Đảng bộ phường, kết quả đạt 03 giải Ba và 01 giải Khuyến khích.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t49","type":"text","x":60,"y":284,"w":680,"rotation":0,"content":"2.3. Đổi mới hình thức tuyên truyền trên môi trường số","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t50","type":"text","x":60,"y":323,"w":680,"rotation":0,"content":"Thực hiện Nghị quyết số 57-NQ/TW của Bộ Chính trị, Ủy ban MTTQ Việt Nam và các tổ chức chính trị - xã hội phường đẩy mạnh ứng dụng công nghệ thông tin, đổi mới phương thức hoạt động theo hướng điều hành trên môi trường số: duy trì sử dụng phần mềm điều hành văn bản, hệ thống “Mặt trận số”, ứng dụng HanoiWork; triển khai họp trực tuyến, trao đổi công việc qua nền tảng số. Trang Fanpage của Ủy ban MTTQ Việt Nam phường và các tổ chức chính trị - xã hội đã đăng tải 185 tin, bài, ảnh, video tuyên truyền; thực hiện 42 video clip, 12 infographic, livestream 05 chương trình, hoạt động lớn của địa phương; chia sẻ trên 280 tin tuyên truyền của các cấp. Tổng lượt tiếp cận đạt khoảng 320.000 lượt, trên 150.000 lượt xem video, hơn 28.000 lượt tương tác và thu hút thêm 1.650 lượt theo dõi mới.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t51","type":"text","x":60,"y":722,"w":680,"rotation":0,"content":"2.4. Tiếp nhận, tổng hợp, phản ánh và phối hợp giải quyết ý kiến, kiến nghị từ cơ sở","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t52","type":"text","x":60,"y":792,"w":680,"rotation":0,"content":"Trong 6 tháng đầu năm 2026, Ủy ban MTTQ Việt Nam phường và các Ban Công tác Mặt trận đã tiếp nhận 185 phản ánh, kiến nghị của Nhân dân qua các kênh (Trang Fanpage, các nhóm Zalo cộng đồng, tiếp công","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (8, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t53","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"dân, Ban Công tác Mặt trận và tổ dân phố); đã chuyển các cơ quan chuyên môn xem xét, giải quyết và trả lời 178 phản ánh, đạt 96,2%. Kết quả tiếp nhận, xử lý phản ánh qua Trang Fanpage gắn với mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay” được nêu cụ thể tại Mục II của Báo cáo này.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t54","type":"text","x":60,"y":249,"w":680,"rotation":0,"content":"Nội dung phản ánh chủ yếu về vệ sinh môi trường, trật tự đô thị, chiếu sáng công cộng, hạ tầng giao thông, an sinh xã hội và công tác giải phóng mặt bằng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t55","type":"text","x":60,"y":367,"w":680,"rotation":0,"content":"Phối hợp với UBND phường tổ chức Hội nghị đại biểu Nhân dân bàn việc xây dựng đời sống văn hóa ở cơ sở theo Kế hoạch liên tịch số 04/KHLT-UBND-UBMTTQ ngày 19/01/2026; chỉ đạo 38/38 tổ dân phố tổ chức hội nghị với trên 2.500 đại biểu tham dự, tổng hợp trên 80 ý kiến, kiến nghị của Nhân dân tập trung vào phát triển kinh tế - văn hóa - xã hội, quản lý đất đai, trật tự đô thị, xây dựng cơ bản, vệ sinh môi trường, các phong trào thi đua và công tác an ninh trật tự.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t56","type":"text","x":60,"y":625,"w":680,"rotation":0,"content":"3. Công tác giám sát, phản biện xã hội, tham gia xây dựng Đảng, xây dựng chính quyền","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t57","type":"text","x":60,"y":700,"w":680,"rotation":0,"content":"3.1. Công tác giám sát","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t58","type":"text","x":60,"y":739,"w":680,"rotation":0,"content":"* Hoạt động giám sát của Ủy ban MTTQ Việt Nam phường","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":true,"italic":false,"align":"left","lineHeight":1.45},{"id":"t59","type":"text","x":60,"y":779,"w":680,"rotation":0,"content":"Trong 6 tháng đầu năm 2026, Ủy ban MTTQ Việt Nam phường đã chủ trì tổ chức 06 cuộc giám sát, phối hợp tham gia 02 cuộc giám sát và tổ chức 01 cuộc khảo sát, tập trung vào các nhiệm vụ chính trị trọng tâm của địa phương, cụ thể:","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (9, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t60","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Chủ trì giám sát công tác chuẩn bị bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031, tập trung vào các nội dung: quy trình hiệp thương, việc lập và niêm yết danh sách cử tri, danh sách người ứng cử, công tác tiếp nhận, giải quyết khiếu nại, tố cáo liên quan đến bầu cử, bảo đảm dân chủ, công khai, đúng quy định pháp luật.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t61","type":"text","x":60,"y":274,"w":680,"rotation":0,"content":"- Tổ chức 03 đoàn giám sát công tác chuẩn bị cơ sở vật chất phục vụ bầu cử, gồm: 01 cuộc giám sát việc niêm yết danh sách cử tri tại 26 khu vực bỏ phiếu; 02 cuộc giám sát công tác trang trí, chuẩn bị các điều kiện phục vụ bầu cử tại các đơn vị bầu cử.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t62","type":"text","x":60,"y":418,"w":680,"rotation":0,"content":"- Thực hiện giám sát đầu tư của cộng đồng đối với 02 công trình, dự án trên địa bàn gồm: Dự án đường Vành đai 4 và Dự án mở rộng Quốc lộ 6.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t63","type":"text","x":60,"y":494,"w":680,"rotation":0,"content":"- Tổ chức 01 cuộc khảo sát về công tác quản lý, sử dụng Quỹ “Vì người nghèo”, Quỹ “Cứu trợ”, Quỹ “Đền ơn đáp nghĩa” tại 38 Ban Công tác Mặt trận tổ dân phố.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t64","type":"text","x":60,"y":604,"w":680,"rotation":0,"content":"- Phối hợp với HĐND phường tham gia 02 cuộc giám sát về công tác bảo đảm vệ sinh an toàn thực phẩm tại các trường học và công tác đầu tư xây dựng cơ bản nhiệm kỳ 2025 - 2030; phối hợp với Ban Kinh tế - Ngân sách HĐND phường khảo sát việc giải quyết các điểm nghẽn về trật tự đô thị trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t65","type":"text","x":60,"y":782,"w":680,"rotation":0,"content":"* Hoạt động của Ban Thanh tra nhân dân","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":true,"italic":false,"align":"left","lineHeight":1.45},{"id":"t66","type":"text","x":60,"y":822,"w":680,"rotation":0,"content":"Thực hiện Luật Thực hiện dân chủ ở cơ sở năm 2022, Nghị định số 59/2023/NĐ-CP ngày 14/8/2023 của Chính phủ và các văn bản hướng","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (10, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t67","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"dẫn của Ủy ban Trung ương MTTQ Việt Nam, Ban Thường trực Ủy ban MTTQ Việt Nam phường đã hướng dẫn tổ chức hội nghị Nhân dân tại các tổ dân phố để bầu Ban Thanh tra nhân dân nhiệm kỳ 2025 - 2028; ban hành Nghị quyết số 01/NQ-MTTQ-BTT ngày 24/11/2025 công nhận Ban Thanh tra nhân dân phường gồm 38 thành viên, bảo đảm mỗi tổ dân phố có 01 đại diện tham gia. Ban đã xây dựng chương trình công tác, phân công nhiệm vụ cụ thể theo địa bàn và duy trì hoạt động ổn định.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t68","type":"text","x":60,"y":354,"w":680,"rotation":0,"content":"Trong 6 tháng đầu năm 2026, Ban Thanh tra nhân dân phường đã triển khai 04 cuộc giám sát, tập trung vào các nội dung:","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t69","type":"text","x":60,"y":436,"w":680,"rotation":0,"content":"- Giám sát công tác bầu cử Tổ trưởng tổ dân phố nhiệm kỳ 2025 - 2028.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t70","type":"text","x":60,"y":478,"w":680,"rotation":0,"content":"- Giám sát công tác chuẩn bị bầu cử đại biểu Quốc hội và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031, gồm: việc niêm yết danh sách cử tri, danh sách người ứng cử, công tác tuyên truyền, bảo đảm an ninh trật tự tại các khu vực bỏ phiếu.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t71","type":"text","x":60,"y":622,"w":680,"rotation":0,"content":"- Giám sát việc thực hiện dân chủ ở cơ sở gắn với công tác thành lập Ban Giám sát đầu tư của cộng đồng tại các tổ dân phố.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t72","type":"text","x":60,"y":698,"w":680,"rotation":0,"content":"- Bên cạnh đó, Ban Thanh tra nhân dân thường xuyên theo dõi, nắm tình hình việc thực hiện chính sách, pháp luật về quản lý đất đai, trật tự xây dựng, công tác bồi thường, giải phóng mặt bằng, giải quyết khiếu nại, tố cáo và việc quản lý, sử dụng các khoản huy động đóng góp của Nhân dân.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (11, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t73","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Qua giám sát, các tổ dân phố và UBND phường cơ bản thực hiện đúng quy trình, bảo đảm công khai, minh bạch; trong kỳ không phát hiện vụ việc vi phạm, không phát sinh kiến nghị, phản ánh thuộc thẩm quyền.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t74","type":"text","x":60,"y":214,"w":680,"rotation":0,"content":"* Hoạt động của Ban Giám sát đầu tư của cộng đồng","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":true,"italic":false,"align":"left","lineHeight":1.45},{"id":"t75","type":"text","x":60,"y":254,"w":680,"rotation":0,"content":"Ban Thường trực Ủy ban MTTQ Việt Nam phường đã hoàn thành việc hiệp thương, bầu cử và ban hành quyết định thành lập 08 Ban Giám sát đầu tư của cộng đồng với 42 thành viên, tương ứng với 08 công trình, dự án triển khai trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t76","type":"text","x":60,"y":407,"w":680,"rotation":0,"content":"Sau khi được thành lập, 100% Ban Giám sát đầu tư của cộng đồng đã xây dựng kế hoạch và tổ chức giám sát thực tế tại công trình, tập trung vào các nội dung: tiến độ thực hiện dự án, việc tuân thủ thiết kế, bản vẽ thi công được phê duyệt, công tác bảo đảm an toàn lao động, an toàn giao thông, vệ sinh môi trường trong quá trình thi công.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t77","type":"text","x":60,"y":595,"w":680,"rotation":0,"content":"Qua hoạt động giám sát, các công trình, dự án cơ bản được triển khai đúng quy định; chưa phát hiện sai sót, vi phạm trong quá trình thực hiện.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t78","type":"text","x":60,"y":677,"w":680,"rotation":0,"content":"Nhìn chung, công tác giám sát của Ủy ban MTTQ Việt Nam phường, Ban Thanh tra nhân dân và Ban Giám sát đầu tư của cộng đồng được triển khai nghiêm túc, đúng chức năng, nhiệm vụ; nội dung giám sát bám sát các nhiệm vụ chính trị trọng tâm của địa phương.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (12, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t79","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Hoạt động của Ban Thanh tra nhân dân và Ban Giám sát đầu tư của cộng đồng từng bước đi vào nền nếp, phát huy vai trò giám sát của Nhân dân, góp phần thực hiện dân chủ ở cơ sở, nâng cao tính công khai, minh bạch trong quản lý nhà nước và phát huy quyền làm chủ của Nhân dân ngay từ giai đoạn đầu triển khai các công trình, dự án trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t80","type":"text","x":60,"y":284,"w":680,"rotation":0,"content":"3.2. Công tác phản biện xã hội","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t81","type":"text","x":60,"y":323,"w":680,"rotation":0,"content":"- Tổ chức hội nghị phản biện, góp ý dự thảo báo cáo tình hình phát triển kinh tế - xã hội của phường 6 tháng đầu năm và nhiệm vụ trọng tâm 6 tháng cuối năm 2026; góp ý 02 Đề án: Nâng cao hiệu quả quản lý nhà nước về cây xanh, vệ sinh môi trường, chỉnh trang đô thị và giải pháp tháo gỡ 05 điểm nghẽn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t82","type":"text","x":60,"y":501,"w":680,"rotation":0,"content":"- Tham gia góp ý vào dự thảo Nghị quyết về Báo cáo kinh tế - xã hội, quốc phòng - an ninh và Nghị quyết về quyết toán ngân sách địa phương năm 2025 tại 03 kỳ họp HĐND phường; phối hợp với Thường trực HĐND phường rà soát nội dung kỳ họp chuyên đề và kỳ họp thường lệ giữa năm 2026 HĐND phường khóa II.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t83","type":"text","x":60,"y":679,"w":680,"rotation":0,"content":"- Hoạt động phản biện xã hội được thực hiện đúng quy trình, bảo đảm khách quan, dân chủ, khoa học; nhiều ý kiến thiết thực liên quan trực tiếp đến đời sống Nhân dân đã được cơ quan soạn thảo tiếp thu, chỉnh sửa.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t84","type":"text","x":60,"y":789,"w":680,"rotation":0,"content":"3.3. Tham gia xây dựng Đảng, xây dựng chính quyền","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4}]'),
  (13, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t85","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Mặt trận Tổ quốc và các tổ chức chính trị - xã hội tích cực tham gia góp ý xây dựng Đảng thông qua hội nghị tiếp xúc cử tri, hội nghị đối thoại giữa người đứng đầu cấp ủy, chính quyền với Nhân dân, sinh hoạt chi bộ và sinh hoạt đoàn thể. Nội dung tập trung vào việc xây dựng và thực hiện nghị quyết, chỉ thị của Đảng; công tác lãnh đạo, chỉ đạo của cấp ủy trong phát triển kinh tế - xã hội, giữ gìn an ninh trật tự; phẩm chất chính trị, đạo đức, lối sống và trách nhiệm nêu gương của cán bộ, đảng viên, nhất là người đứng đầu. Đã tham gia đóng góp ý kiến vào 10 chương trình, đề án của Đảng bộ phường nhiệm kỳ 2025 - 2030; tuyên truyền, vận động Nhân dân đồng thuận thực hiện 05 Đề án chiến lược của Đảng ủy phường giai đoạn 2026 - 2030 (Chuyển đổi số; Nông nghiệp đô thị xanh; Thương mại - Du lịch; Giáo dục; Quản lý quy hoạch đô thị).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t86","type":"text","x":60,"y":530,"w":680,"rotation":0,"content":"Tham gia góp ý xây dựng chính quyền thông qua giám sát, phản ánh ý kiến, kiến nghị của Nhân dân đối với hoạt động của chính quyền, cán bộ, công chức, tập trung vào việc thực hiện cải cách hành chính, nâng cao chất lượng phục vụ Nhân dân; thực hiện các chính sách an sinh xã hội; thực hiện quy chế dân chủ ở cơ sở, công tác tiếp dân và giải quyết đơn thư khiếu nại, tố cáo. Các ý kiến góp ý được cấp ủy, chính quyền tiếp thu, xem xét, giải quyết kịp thời.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t87","type":"text","x":60,"y":788,"w":680,"rotation":0,"content":"4. Các phong trào thi đua, cuộc vận động và nhiệm vụ chính trị trọng tâm","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t88","type":"text","x":60,"y":863,"w":680,"rotation":0,"content":"4.1. Công tác Mặt trận tham gia cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4}]'),
  (14, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t89","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Đây là nhiệm vụ chính trị trọng tâm của 6 tháng đầu năm. Ban Thường trực Ủy ban MTTQ Việt Nam phường đã chủ động triển khai toàn diện, nghiêm túc từ phổ biến, tuyên truyền, quán triệt đến tổ chức thực hiện các nhiệm vụ cụ thể theo đúng Chỉ thị của Bộ Chính trị và quy định pháp luật, bảo đảm thống nhất, không để xảy ra sai sót.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t90","type":"text","x":60,"y":284,"w":680,"rotation":0,"content":"- Chủ trì tổ chức thành công, đúng luật, đúng tiến độ 03 Hội nghị hiệp thương để thỏa thuận cơ cấu, thành phần và lập danh sách sơ bộ người ứng cử đại biểu HĐND phường khóa II.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t91","type":"text","x":60,"y":394,"w":680,"rotation":0,"content":"- Chủ trì tổ chức 17 Hội nghị lấy ý kiến nhận xét và tín nhiệm của cử tri nơi cư trú đối với những người ứng cử, bảo đảm dân chủ, công khai, khách quan.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t92","type":"text","x":60,"y":470,"w":680,"rotation":0,"content":"- Chủ trì tổ chức 37 Hội nghị tiếp xúc cử tri để người ứng cử báo cáo chương trình hành động và thực hiện quyền vận động bầu cử (02 hội nghị tiếp sóng đại biểu Quốc hội và HĐND Thành phố; 35 hội nghị trực tiếp của đại biểu HĐND phường).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t93","type":"text","x":60,"y":614,"w":680,"rotation":0,"content":"- Phát huy vai trò giám sát bầu cử: thành lập 02 đoàn giám sát độc lập, cử cán bộ tham gia các đoàn giám sát, khảo sát; bám sát cơ sở kiểm tra việc lập, niêm yết danh sách cử tri, giải quyết khiếu nại, tố cáo và chuẩn bị cơ sở vật chất tại các khu vực bỏ phiếu.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t94","type":"text","x":60,"y":758,"w":680,"rotation":0,"content":"- Trong ngày bầu cử, MTTQ và các đoàn thể tập trung tuyên truyền, vận động cử tri đi bầu đúng - bầu đủ cơ cấu, số lượng, tỉ lệ phiếu bầu đạt 96,6%.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (15, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t95","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Kết quả cuộc bầu cử đã khẳng định sự lãnh đạo sâu sát, kịp thời và hiệu quả của Đảng ủy phường trong công tác chỉ đạo, điều hành; sự phối hợp chặt chẽ, đồng bộ của chính quyền, Ủy ban MTTQ Việt Nam và các tổ chức chính trị - xã hội phường trong triển khai thực hiện các nhiệm vụ bầu cử. Công tác tuyên truyền được đổi mới về nội dung và hình thức, bám sát cơ sở, góp phần nâng cao nhận thức, ý thức trách nhiệm của cử tri, tạo sự đồng thuận cao trong Nhân dân. Qua đó, củng cố niềm tin của Nhân dân đối với sự lãnh đạo của Đảng, sự quản lý, điều hành của chính quyền và vai trò tập hợp, phát huy khối đại đoàn kết toàn dân tộc của MTTQ Việt Nam; đồng thời tiếp tục khẳng định tinh thần dân chủ, đoàn kết, trách nhiệm của Nhân dân trong tham gia xây dựng chính quyền địa phương vững mạnh.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t96","type":"text","x":60,"y":495,"w":680,"rotation":0,"content":"- Kết quả khen thưởng: UBND thành phố Hà Nội khen thưởng tập thể có thành tích xuất sắc và cá nhân đồng chí Chủ tịch Ủy ban MTTQ Việt Nam phường; Ủy ban MTTQ Việt Nam Thành phố khen thưởng 01 Ban Công tác Mặt trận và 01 đồng chí Trưởng ban Công tác Mặt trận; UBND phường khen thưởng 4/4 đồng chí Phó Chủ tịch Ủy ban MTTQ và 5/5 đồng chí chuyên viên cơ quan.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t97","type":"text","x":60,"y":708,"w":680,"rotation":0,"content":"- Tổ chức Hội nghị tổng kết công tác Mặt trận tham gia cuộc bầu cử; đồng thời chỉ đạo 38/38 Ban Công tác Mặt trận chia thành 10 cụm thi đua ký giao ước thi đua năm 2026. Tại hội nghị đã khen thưởng 38 tập thể và 86 cá nhân có thành tích xuất sắc.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t98","type":"text","x":60,"y":852,"w":680,"rotation":0,"content":"4.2. Chăm lo an sinh xã hội, tổ chức các hoạt động Mừng Đảng - Mừng Xuân Bính Ngọ 2026","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4}]'),
  (16, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t99","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Quán triệt sâu sắc Chỉ thị số 55-CT/TW của Ban Bí thư và Chỉ thị số 05-CT/TU của Thành ủy, Ủy ban MTTQ Việt Nam phường đã huy động tối đa các nguồn lực xã hội hóa với tinh thần “tương thân, tương ái”, bảo đảm mọi người dân đều có Tết. Tổ chức thành công Chương trình “Tết đoàn viên - Kết yêu thương 2026” với nhiều hoạt động văn hóa cổ truyền (gói bánh chưng, làm bao lì xì, gian hàng 0 đồng...). Kết quả cụ thể:","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t100","type":"text","x":60,"y":319,"w":680,"rotation":0,"content":"- Trích Quỹ “Vì người nghèo” tặng 55 suất quà trị giá 27.500.000 đồng và hỗ trợ học tập năm 2026 cho 18 cháu học sinh là con em các hộ mới thoát cận nghèo với số tiền 54.000.000 đồng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t101","type":"text","x":60,"y":429,"w":680,"rotation":0,"content":"- Nguồn xã hội hóa: tặng 65 suất quà trị giá 13.000.000 đồng cho các hộ có hoàn cảnh khó khăn, người khuyết tật.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t102","type":"text","x":60,"y":505,"w":680,"rotation":0,"content":"- Phối hợp với UBND phường vận động doanh nghiệp, nhà hảo tâm tặng 100 suất quà trị giá 100.000.000 đồng (phối hợp với Ngân hàng Nông nghiệp và Phát triển nông thôn).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t103","type":"text","x":60,"y":615,"w":680,"rotation":0,"content":"- Nhân dịp Tết Thiếu nhi, tặng 34 suất quà trị giá 34.000.000 đồng, mỗi suất gồm nhu yếu phẩm (nguồn xã hội hóa) và tiền mặt 500.000 đồng (trích Quỹ “Vì người nghèo”).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t104","type":"text","x":60,"y":725,"w":680,"rotation":0,"content":"- Công tác hậu phương quân đội: gặp mặt, động viên và trao tặng quà cho 56 thanh niên lên đường nhập ngũ và quân nhân xuất ngũ với tổng số tiền 11.800.000 đồng; phối hợp tổ chức các buổi nói chuyện truyền thống cho học sinh nhân kỷ niệm 81 năm Ngày thành lập Quân đội nhân dân Việt Nam và 36 năm Ngày hội Quốc phòng toàn dân.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (17, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t105","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Thực hiện tốt đạo lý “Uống nước nhớ nguồn” thông qua lễ dâng hương, viếng Nghĩa trang liệt sĩ nhân dịp Tết Nguyên đán và các dịp lễ.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t106","type":"text","x":60,"y":172,"w":680,"rotation":0,"content":"4.3. Các cuộc vận động, phong trào thi đua yêu nước","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t107","type":"text","x":60,"y":211,"w":680,"rotation":0,"content":"Ủy ban MTTQ Việt Nam phường tiếp tục triển khai hiệu quả các cuộc vận động và phong trào thi đua yêu nước gắn với nhiệm vụ chính trị của địa phương, góp phần củng cố khối đại đoàn kết toàn dân tộc, phát huy sức mạnh Nhân dân tham gia phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh và xây dựng đô thị văn minh.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t108","type":"text","x":60,"y":399,"w":680,"rotation":0,"content":"Cuộc vận động \"Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh\" được triển khai với nhiều nội dung, hình thức phong phú, thiết thực; phát huy vai trò tự quản của cộng đồng dân cư trong giữ gìn vệ sinh môi trường, xây dựng cảnh quan đô thị, phát triển kinh tế, giảm nghèo bền vững, bảo tồn và phát huy các giá trị văn hóa truyền thống. Việc thực hiện nếp sống văn minh trong việc cưới, việc tang, mừng thọ và lễ hội tiếp tục được duy trì, tạo chuyển biến tích cực trong đời sống văn hóa ở khu dân cư.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t109","type":"text","x":60,"y":657,"w":680,"rotation":0,"content":"Cuộc vận động \"Người Việt Nam ưu tiên dùng hàng Việt Nam\" được triển khai thường xuyên; thực hiện chế độ báo cáo kết quả theo quý, góp phần nâng cao nhận thức của cán bộ, đoàn viên, hội viên và Nhân dân về ưu tiên sử dụng hàng hóa sản xuất trong nước.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t110","type":"text","x":60,"y":810,"w":680,"rotation":0,"content":"Công tác tổ chức Ngày hội Đại đoàn kết toàn dân tộc ở khu dân cư được chỉ đạo đồng bộ tại 100% Ban Công tác Mặt trận tổ dân phố, bảo đảm trang trọng, thiết thực, tạo không khí đoàn kết, gắn bó trong cộng đồng","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (18, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t111","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"dân cư. Dịp này, 114 hộ gia đình tiêu biểu được biểu dương, khen thưởng; Ủy ban MTTQ Việt Nam phường trao 51 suất quà, tổng trị giá 25.500.000 đồng, cho các hộ có hoàn cảnh khó khăn và học sinh vượt khó, chăm ngoan.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t112","type":"text","x":60,"y":214,"w":680,"rotation":0,"content":"Trong phong trào \"Toàn dân đoàn kết xây dựng đời sống văn hóa\", Ủy ban MTTQ Việt Nam phường phối hợp UBND phường ban hành Kế hoạch liên tịch, chỉ đạo 38/38 Ban Công tác Mặt trận tổ chức thành công Hội nghị đại biểu Nhân dân bàn việc xây dựng đời sống văn hóa ở cơ sở và hội nghị cấp phường năm 2026, góp phần phát huy quyền làm chủ của Nhân dân trong xây dựng đời sống văn hóa tại địa bàn dân cư.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t113","type":"text","x":60,"y":437,"w":680,"rotation":0,"content":"Công tác tôn giáo được quan tâm thực hiện. Ủy ban MTTQ Việt Nam phường tổ chức các đoàn đến thăm, chúc mừng các cơ sở tôn giáo nhân dịp Đại lễ Phật đản năm 2026; động viên chức sắc, tăng ni, phật tử tiếp tục chấp hành tốt chủ trương của Đảng, chính sách, pháp luật của Nhà nước, tích cực tham gia các phong trào thi đua yêu nước và các hoạt động vì cộng đồng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t114","type":"text","x":60,"y":625,"w":680,"rotation":0,"content":"Phong trào bảo vệ môi trường, xây dựng đô thị văn minh tiếp tục được đẩy mạnh. Ủy ban MTTQ Việt Nam phường chủ trì tổ chức 05 đợt ra quân tổng vệ sinh môi trường gắn với nhiệm vụ tháo gỡ \"05 điểm nghẽn\" của Thành phố; phối hợp chặt chẽ với Công an phường sử dụng 04 xe tuyên truyền lưu động trên các tuyến đường chính, tổ chức bóc xóa biển quảng cáo, rao vặt sai quy định, xử lý các điểm tồn đọng rác thải tại khu vực giáp ranh, đất trống.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (19, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t115","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Đồng thời phát động phong trào thi đua \"Toàn dân chung tay bảo vệ môi trường, vì Thủ đô Sáng - Xanh - Sạch - Đẹp\" hưởng ứng Ngày Môi trường thế giới (05/6) và Tháng hành động vì môi trường năm 2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t116","type":"text","x":60,"y":214,"w":680,"rotation":0,"content":"Ủy ban MTTQ Việt Nam phường và các tổ chức chính trị - xã hội tiếp tục phát huy vai trò nòng cốt trong công tác tuyên truyền, vận động Nhân dân thông qua các đợt ra quân đồng loạt tại cơ sở, tuyên truyền lưu động, truyền thông trực quan, hệ thống mạng xã hội và các nhóm Zalo cộng đồng; góp phần nâng cao ý thức giữ gìn vệ sinh môi trường, xây dựng nếp sống văn minh đô thị, tạo sức lan tỏa mạnh mẽ phong trào thi đua \"Sáng - Xanh - Sạch - Đẹp\" trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t117","type":"text","x":60,"y":472,"w":680,"rotation":0,"content":"Thực hiện nhiệm vụ bảo đảm an ninh trật tự, Ủy ban MTTQ Việt Nam phường phối hợp với Công an phường ký kết Chương trình phối hợp thực hiện phong trào \"Toàn dân bảo vệ an ninh Tổ quốc\" giai đoạn 2026 - 2030; đẩy mạnh tuyên truyền, vận động Nhân dân tích cực tham gia phòng, chống tội phạm, tệ nạn xã hội, giữ gìn an ninh chính trị, trật tự an toàn xã hội, xây dựng khu dân cư an toàn, văn minh; tiếp tục phát huy hiệu quả các mô hình tự quản, góp phần giữ vững ổn định tình hình ngay từ cơ sở.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t118","type":"text","x":60,"y":730,"w":680,"rotation":0,"content":"Công tác tuyên truyền, vận động Nhân dân tham gia các nhiệm vụ chính trị trọng tâm được triển khai đồng bộ.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (20, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t119","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nhân dịp kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27/7/1947 - 27/7/2026), MTTQ và các tổ chức chính trị - xã hội đã vận động cán bộ, đoàn viên, hội viên và Nhân dân tích cực tham gia các hoạt động tri ân như dâng hương, thăm hỏi, tặng quà người có công, gia đình chính sách; vệ sinh, chỉnh trang nghĩa trang liệt sĩ và các công trình ghi công liệt sĩ, góp phần giáo dục truyền thống yêu nước và đạo lý \"Uống nước nhớ nguồn\". Đồng thời, tập trung tuyên truyền, vận động Nhân dân hưởng ứng các đợt cao điểm của Thành phố và địa phương như 45 ngày đêm hoàn thiện dữ liệu đất đai, 100 ngày đêm đẩy mạnh chuyển đổi số và 500 ngày đêm tìm kiếm, quy tập, xác định danh tính hài cốt liệt sĩ còn thiếu thông tin, tạo sự thống nhất trong nhận thức và huy động sự tham gia tích cực của các tầng lớp Nhân dân đối với các nhiệm vụ chính trị trọng tâm.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t120","type":"text","x":60,"y":530,"w":680,"rotation":0,"content":"Công tác vận động các nguồn lực xã hội tiếp tục đạt kết quả tích cực. Quỹ \"Vì biển, đảo Việt Nam\" năm 2026 vận động được 237.902.200 đồng, đã chuyển toàn bộ về Ủy ban MTTQ Việt Nam Thành phố; đồng thời biểu dương 03 tập thể tiêu biểu có thành tích xuất sắc trong vận động Quỹ gồm: Trường Tiểu học Yên Nghĩa (93.558.000 đồng), Trường Trung học Yên Nghĩa (27.122.000 đồng) và Tổ dân phố số 21 (10.500.000 đồng).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t121","type":"text","x":60,"y":753,"w":680,"rotation":0,"content":"Tham gia thực hiện nhiệm vụ tháo gỡ \"05 điểm nghẽn\" của Thành phố, Ủy ban MTTQ Việt Nam phường tiếp tục duy trì và phát huy hiệu quả 03 mô hình trọng tâm gồm: Tổ tuyên truyền tháo gỡ \"05 điểm nghẽn\", Tổ tuyên truyền giải phóng mặt bằng Quốc lộ 6 và mô hình \"Alo - Đoàn kết","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (21, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t122","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"vì Yên Nghĩa hôm nay\", góp phần nâng cao hiệu quả công tác tuyên truyền, tạo sự đồng thuận của Nhân dân trong triển khai các nhiệm vụ phát triển kinh tế - xã hội trên địa bàn (chi tiết tại Mục II).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t123","type":"text","x":60,"y":214,"w":680,"rotation":0,"content":"5. Công tác xây dựng tổ chức, phát triển đoàn viên, hội viên","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t124","type":"text","x":60,"y":256,"w":680,"rotation":0,"content":"5.1. Tình hình tổ chức, cán bộ và củng cố tổ chức ở cơ sở","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t125","type":"text","x":60,"y":295,"w":680,"rotation":0,"content":"Thực hiện sắp xếp đơn vị hành chính và sáp nhập tổ dân phố, từ ngày 01/7/2026 địa bàn phường còn 15 tổ dân phố. Ủy ban MTTQ Việt Nam phường đang tập trung chỉ đạo kiện toàn Ban Công tác Mặt trận, các chi hội, chi đoàn tại 15 tổ dân phố mới; đồng thời kiện toàn Ban Thanh tra nhân dân và Ban Giám sát đầu tư của cộng đồng theo cơ cấu tổ chức mới, bảo đảm hoạt động liên tục, không gián đoạn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t126","type":"text","x":60,"y":518,"w":680,"rotation":0,"content":"Ủy ban MTTQ Việt Nam phường phối hợp với UBND phường chỉ đạo hợp nhất các Hội quần chúng; các Hội bước đầu đã đi vào hoạt động có hiệu quả, góp phần đoàn kết, tập hợp hội viên và tích cực tham gia các hoạt động xã hội tại cơ sở.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t127","type":"text","x":60,"y":671,"w":680,"rotation":0,"content":"5.2. Kết quả tập hợp, phát triển, quản lý đoàn viên, hội viên","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t128","type":"text","x":60,"y":710,"w":680,"rotation":0,"content":"- Hội LHPN phường: quản lý hiệu quả 16 Tổ Tiết kiệm và Vay vốn Ngân hàng Chính sách xã hội với 813 hộ vay, tổng dư nợ 63.544.100.000 đồng; các hộ vay sử dụng vốn đúng mục đích, không có nợ quá hạn, nợ chây ỳ. Tiếp tục cập nhật dữ liệu hội viên lên phần mềm của Trung ương Hội và iHanoi. Cử 02 đồng chí Thường trực Hội tham gia đội ngũ báo cáo viên, báo cáo viên pháp luật do Hội LHPN Thành phố quản lý.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (22, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t129","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Đoàn TNCS Hồ Chí Minh phường: kết nạp 115 đoàn viên mới tại Trường THCS Đồng Mai và Trường THCS Yên Nghĩa; tổ chức cho 30 đoàn viên ưu tú đi thăm quan địa chỉ đỏ tại Văn Miếu - Quốc Tử Giám và Nhà tù Hỏa Lò; triển khai sinh hoạt chi đoàn chủ điểm tại chi đoàn tổ dân phố; quản lý tốt 03 Tổ vay vốn Ngân hàng Chính sách xã hội với dư nợ trên 12 tỷ đồng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t130","type":"text","x":60,"y":274,"w":680,"rotation":0,"content":"- Hội Cựu chiến binh phường: tổng hợp kết quả kê khai các đối tượng cựu chiến binh, cựu quân nhân chưa được hưởng BHXH, BHYT báo cáo Hội Cựu chiến binh Thành phố; phối hợp với Ban Chỉ huy quân sự rà soát danh sách hội viên thuộc lực lượng vũ trang Bộ Tư lệnh Thủ đô qua các thời kỳ; quản lý tốt 07 Tổ vay vốn Ngân hàng Chính sách xã hội với dư nợ trên 32 tỷ đồng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t131","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"- Công đoàn phường: ứng dụng công nghệ thông tin quản lý dữ liệu 1.021 đoàn viên; tiếp tục triển khai việc cập nhật tổ chức công đoàn và đoàn viên trên ứng dụng iHanoi; tiếp tục rà soát các công ty, đơn vị đủ điều kiện để vận động thành lập công đoàn cơ sở.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t132","type":"text","x":60,"y":631,"w":680,"rotation":0,"content":"- Ban Công tác Mặt trận các tổ dân phố phát huy vai trò nòng cốt trong công tác dân vận, tham gia giải phóng mặt bằng các dự án trọng điểm, giám sát đầu tư của cộng đồng, hòa giải ở cơ sở và xây dựng khối đại đoàn kết toàn dân tộc; các nhóm Zalo cộng đồng tiếp tục phát huy hiệu quả trong tuyên truyền và nắm bắt dư luận Nhân dân.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t133","type":"text","x":60,"y":809,"w":680,"rotation":0,"content":"6. Công tác phối hợp","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35}]'),
  (23, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t134","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Phối hợp với UBND phường ban hành và triển khai Kế hoạch liên tịch số 04/KHLT-UBND-UBMTTQ ngày 19/01/2026 về tổ chức Hội nghị đại biểu Nhân dân bàn việc xây dựng đời sống văn hóa ở cơ sở năm 2026 và Kế hoạch phối hợp số 20/KHPH-UBND-UBMTTQ ngày 08/5/2026 về tổ chức bầu thành viên Ban Giám sát đầu tư của cộng đồng đối với các chương trình, dự án đầu tư công trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t135","type":"text","x":60,"y":309,"w":680,"rotation":0,"content":"- Phối hợp với Thường trực HĐND phường trong giám sát, khảo sát, rà soát nội dung các kỳ họp; phối hợp tổ chức tiếp xúc cử tri trước và sau kỳ họp.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t136","type":"text","x":60,"y":385,"w":680,"rotation":0,"content":"- Phối hợp với Công an phường trong các đợt ra quân tổng vệ sinh môi trường, bảo đảm an ninh trật tự tại các khu vực bỏ phiếu và địa bàn thi công dự án.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t137","type":"text","x":60,"y":495,"w":680,"rotation":0,"content":"- Phối hợp với Ngân hàng Chính sách xã hội trong quản lý, giải ngân, kiểm tra sử dụng nguồn vốn ủy thác qua các tổ chức chính trị - xã hội.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t138","type":"text","x":60,"y":571,"w":680,"rotation":0,"content":"- Phối hợp với các cơ sở tôn giáo trong vận động xây dựng đời sống văn hóa, bảo vệ môi trường và giữ gìn an ninh trật tự.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t139","type":"text","x":60,"y":647,"w":680,"rotation":0,"content":"- Khó khăn, bất cập cần khắc phục: việc phối hợp xử lý, trả lời các phản ánh, kiến nghị của Nhân dân qua nền tảng số có lúc còn chậm do phụ thuộc tiến độ của cơ quan chuyên môn; một số tổ chức thành viên chưa chủ động cung cấp tin, bài phục vụ công tác tuyên truyền; kinh phí hoạt động của MTTQ và các đoàn thể chính trị - xã hội chưa đáp ứng yêu cầu nhiệm vụ; cơ sở vật chất phục vụ sinh hoạt cộng đồng tại một số tổ dân phố sau sáp nhập còn thiếu.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (24, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t140","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Nhìn chung, trong 6 tháng đầu năm 2026, công tác Mặt trận và các tổ chức chính trị - xã hội phường tiếp tục bám sát sự lãnh đạo, chỉ đạo của Đảng ủy phường, Ban Thường trực Ủy ban MTTQ Việt Nam Thành phố và yêu cầu nhiệm vụ chính trị của địa phương; chủ động đổi mới nội dung, phương thức hoạt động, phát huy vai trò nòng cốt trong xây dựng khối đại đoàn kết toàn dân tộc, góp phần giữ vững ổn định chính trị, tạo sự đồng thuận xã hội và thực hiện thắng lợi các nhiệm vụ phát triển kinh tế - xã hội, quốc phòng, an ninh trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t141","type":"text","x":60,"y":390,"w":680,"rotation":0,"content":"II. KẾT QUẢ TRIỂN KHAI PHONG TRÀO THI ĐUA “DÂN VẬN KHÉO”","fontSize":27,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.3},{"id":"t142","type":"text","x":60,"y":472,"w":680,"rotation":0,"content":"1. Công tác triển khai","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t143","type":"text","x":60,"y":514,"w":680,"rotation":0,"content":"Ban Thường trực Ủy ban MTTQ Việt Nam phường đã quán triệt, triển khai phong trào thi đua “Dân vận khéo” đến toàn thể cán bộ, đoàn viên, hội viên và các Ban Công tác Mặt trận; chỉ đạo các tổ chức chính trị - xã hội lựa chọn, đăng ký mô hình, phần việc gắn với nhiệm vụ chính trị trọng tâm của phường, nhất là công tác bầu cử, giải phóng mặt bằng các dự án trọng điểm, giải quyết “05 điểm nghẽn” và chuyển đổi số.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t144","type":"text","x":60,"y":737,"w":680,"rotation":0,"content":"Thường trực Ủy ban MTTQ Việt Nam phường phân công rõ trách nhiệm tập thể, cá nhân chủ trì từng mô hình;","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (25, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t145","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"trong đó phân công đồng chí Phó Chủ tịch Ủy ban MTTQ Việt Nam phường, Bí thư Đoàn phường chủ trì tham mưu hoàn thiện hồ sơ, văn bản và tổ chức vận hành Trang Fanpage của Ủy ban MTTQ Việt Nam phường và các tổ chức chính trị - xã hội gắn với mô hình “Alo Đoàn kết vì Yên Nghĩa hôm nay”.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t146","type":"text","x":60,"y":284,"w":680,"rotation":0,"content":"2. Kết quả các mô hình, phần việc","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t147","type":"text","x":60,"y":326,"w":680,"rotation":0,"content":"2.1. Mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay”","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t148","type":"text","x":60,"y":365,"w":680,"rotation":0,"content":"- Về hệ thống văn bản: đã nghiên cứu, xây dựng và hoàn thiện 01 Kế hoạch triển khai mô hình; 01 Quy chế quản lý và vận hành Fanpage; 01 Quy chế phối hợp giữa Ủy ban MTTQ Việt Nam phường với các tổ chức chính trị - xã hội trong công tác tuyên truyền trên môi trường số; 01 Quy trình tiếp nhận, xử lý và phản hồi thông tin của Nhân dân thông qua Fanpage; 01 Báo cáo tổng hợp kết quả triển khai mô hình. Đồng thời xây dựng bộ tiêu chí đánh giá hiệu quả hoạt động của Fanpage theo các chỉ số: lượng tin bài, lượt tiếp cận, lượt tương tác, phản ánh của Nhân dân và kết quả xử lý.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t149","type":"text","x":60,"y":646,"w":680,"rotation":0,"content":"- Về kết quả tuyên truyền: đăng tải 185 tin, bài, ảnh và video; thực hiện 42 video clip tuyên truyền; 12 infographic về chuyển đổi số, cải cách hành chính, an sinh xã hội, vệ sinh môi trường, xây dựng đô thị văn minh; livestream 05 chương trình, hoạt động lớn của địa phương; duy trì tần suất đăng 4 - 6 tin, bài/tuần.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t150","type":"text","x":60,"y":824,"w":680,"rotation":0,"content":"- Về hiệu quả truyền thông: tổng lượt tiếp cận đạt khoảng 320.000 lượt; tổng lượt xem video đạt trên 150.000 lượt; hơn 28.000 lượt tương tác (thích, bình luận, chia sẻ); thu hút thêm 1.650 lượt theo dõi mới.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (26, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t151","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Về tiếp nhận và xử lý phản ánh: thông qua Fanpage đã tiếp nhận 68 phản ánh, kiến nghị của Nhân dân; chuyển cơ quan chuyên môn xử lý 68/68 phản ánh; đã giải quyết dứt điểm 60 vụ việc, đạt 88,2%. Nội dung chủ yếu về vệ sinh môi trường, trật tự đô thị, chiếu sáng công cộng, hạ tầng giao thông, an sinh xã hội và giải phóng mặt bằng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t152","type":"text","x":60,"y":274,"w":680,"rotation":0,"content":"- Nội dung tuyên truyền tập trung vào chủ trương của Đảng, chính sách pháp luật của Nhà nước; công tác xây dựng Đảng, xây dựng chính quyền; các phong trào thi đua yêu nước và Cuộc vận động “Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh”; công tác giải phóng mặt bằng, vệ sinh môi trường; chuyển đổi số; hoạt động của Đoàn Thanh niên, Hội Liên hiệp Phụ nữ, Hội Cựu chiến binh, Công đoàn phường; công tác an sinh xã hội và các hoạt động tri ân, đền ơn đáp nghĩa.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t153","type":"text","x":60,"y":521,"w":680,"rotation":0,"content":"Mô hình đã góp phần tăng cường sự gắn kết giữa cấp ủy, chính quyền với Nhân dân; nâng cao hiệu quả công tác dân vận và công tác giám sát của Mặt trận Tổ quốc trên môi trường số.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t154","type":"text","x":60,"y":639,"w":680,"rotation":0,"content":"2.2. Các mô hình, phần việc khác","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t155","type":"text","x":60,"y":678,"w":680,"rotation":0,"content":"- Tổ tuyên truyền tháo gỡ 05 điểm nghẽn: tập trung xử lý các vấn đề dân sinh, trật tự đô thị, vệ sinh môi trường và chuyển đổi số; chủ trì 05 đợt ra quân tổng vệ sinh môi trường với sự phối hợp của Công an phường và 04 xe tuyên truyền lưu động, xử lý dứt điểm các “điểm đen” về chân rác.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t156","type":"text","x":60,"y":822,"w":680,"rotation":0,"content":"- Tổ tuyên truyền giải phóng mặt bằng Quốc lộ 6: bám sát địa bàn, kiên trì vận động Nhân dân đồng thuận với chính sách bồi thường, hỗ trợ; kịp thời tiếp nhận và phối hợp xử lý kiến nghị của các hộ dân.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (27, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t157","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Hội LHPN phường triển khai mô hình “Đổi phế liệu, gây quỹ từ thiện”, mô hình “Đến từng ngõ, gõ từng nhà - Phụ nữ Yên Nghĩa đồng hành cùng dự án Quốc lộ 6” và duy trì chương trình “Mẹ đỡ đầu” (hỗ trợ 02 cháu mồ côi có hoàn cảnh khó khăn với mức 1.000.000 đồng/cháu/tháng).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t158","type":"text","x":60,"y":240,"w":680,"rotation":0,"content":"- Đoàn TNCS Hồ Chí Minh phường duy trì mô hình “Em nuôi của Đoàn”; ra mắt “Bản đồ số thông tin về bầu cử” HĐND các cấp; tổ chức Hội nghị mạn đàm cử tri trẻ với hơn 200 đoàn viên, thanh niên tham gia; huy động trên 200 đoàn viên tham gia vệ sinh môi trường trong Tháng Thanh niên; xây dựng kế hoạch số hóa dữ liệu di tích lịch sử trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t159","type":"text","x":60,"y":418,"w":680,"rotation":0,"content":"- Hội Cựu chiến binh phường tích cực thực hiện Nghị quyết số 35-NQ/TW của Bộ Chính trị về bảo vệ nền tảng tư tưởng của Đảng; cử 40 lượt hội viên tham gia 03 cuộc phản biện xã hội với 22 lượt ý kiến đóng góp về kế hoạch phát triển kinh tế - xã hội, chính sách người có công, công tác bồi thường, hỗ trợ giải phóng mặt bằng các dự án trọng điểm; tham gia hàng chục buổi đối thoại với người dân trong diện giải phóng mặt bằng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t160","type":"text","x":60,"y":631,"w":680,"rotation":0,"content":"- Công đoàn phường tổ chức phát động Tháng hành động về an toàn, vệ sinh lao động; tổ chức thăm khám, tư vấn sức khỏe miễn phí cho trên 200 đoàn viên công đoàn cơ sở; thăm hỏi, tặng quà 17 đoàn viên bị tai nạn lao động, bệnh nghề nghiệp hoặc có hoàn cảnh đặc biệt khó khăn với tổng số tiền 8.500.000 đồng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t161","type":"text","x":60,"y":809,"w":680,"rotation":0,"content":"3. Hiệu quả và khả năng nhân rộng","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35}]'),
  (28, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t162","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Mô hình thực sự hiệu quả, có cách làm mới, có thể duy trì và nhân rộng: mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay” (có quy trình, quy chế và bộ tiêu chí đánh giá rõ ràng, số liệu đo lường được, giải quyết trực tiếp vấn đề dân sinh ở cơ sở); mô hình “Đến từng ngõ, gõ từng nhà - Phụ nữ Yên Nghĩa đồng hành cùng dự án Quốc lộ 6” và Tổ tuyên truyền giải phóng mặt bằng Quốc lộ 6 (gắn trực tiếp với nhiệm vụ chính trị trọng tâm, tạo đồng thuận trong Nhân dân).","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t163","type":"text","x":60,"y":343,"w":680,"rotation":0,"content":"- Mô hình hiệu quả chưa rõ, còn hình thức hoặc cần điều chỉnh: một số mô hình của các tổ chức thành viên chưa lượng hóa được kết quả bằng số liệu cụ thể, chưa có tiêu chí đánh giá; việc duy trì phụ thuộc nhiều vào một số cá nhân nòng cốt. Nguyên nhân chủ yếu: cán bộ cơ sở kiêm nhiệm nhiều việc, kỹ năng ứng dụng công nghệ thông tin của một bộ phận cán bộ còn hạn chế; kinh phí duy trì mô hình chủ yếu từ xã hội hóa nên chưa ổn định; một số tổ chức thành viên chưa chủ động cung cấp tin, bài, chất lượng hình ảnh, video chưa đồng đều.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t164","type":"text","x":60,"y":624,"w":680,"rotation":0,"content":"4. Đề xuất nhiệm vụ 6 tháng cuối năm 2026","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t165","type":"text","x":60,"y":666,"w":680,"rotation":0,"content":"- Tiếp tục duy trì, nâng cao chất lượng mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay” gắn với chuyển đổi số và xây dựng chính quyền số: phấn đấu mỗi tuần đăng tối thiểu 05 - 07 tin, bài; mỗi tháng xây dựng ít nhất 03 video tuyên truyền; duy trì phản hồi các phản ánh của Nhân dân trong thời gian từ 24 - 48 giờ; nâng tổng lượng người theo dõi Fanpage lên trên 5.000 người.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (29, '#ffffff', '/tin/bg-trang.webp', '[{"id":"s221","type":"shape","x":54,"y":501,"w":70,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s222","type":"shape","x":122,"y":501,"w":164,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s223","type":"shape","x":284,"y":501,"w":135,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s224","type":"shape","x":417,"y":501,"w":179,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s225","type":"shape","x":594,"y":501,"w":152,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s261","type":"shape","x":54,"y":585,"w":70,"h":297,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s262","type":"shape","x":122,"y":585,"w":164,"h":297,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s263","type":"shape","x":284,"y":585,"w":135,"h":297,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s264","type":"shape","x":417,"y":585,"w":179,"h":297,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s265","type":"shape","x":594,"y":585,"w":152,"h":297,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"t301","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Nhân rộng mô hình “Đổi phế liệu, gây quỹ từ thiện” và các mô hình tự quản về vệ sinh môi trường tại 15 tổ dân phố sau sắp xếp.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t302","type":"text","x":60,"y":172,"w":680,"rotation":0,"content":"- Điều chỉnh, bổ sung tiêu chí đánh giá và chế độ báo cáo định kỳ đối với các mô hình của các tổ chức thành viên; yêu cầu mỗi tổ chức chính trị - xã hội đăng ký ít nhất 01 mô hình “Dân vận khéo” có sản phẩm cụ thể, đo lường được đến ngày 31/12/2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t303","type":"text","x":60,"y":316,"w":680,"rotation":0,"content":"- Xây dựng mới mô hình “Dân vận khéo” trong công tác vận động Nhân dân ổn định sinh hoạt cộng đồng sau sáp nhập tổ dân phố, do Ban Thường trực Ủy ban MTTQ Việt Nam phường chủ trì, phối hợp với các chi bộ và Ban Công tác Mặt trận 15 tổ dân phố.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t304","type":"text","x":60,"y":460,"w":680,"rotation":0,"content":"Biểu tổng hợp mô hình, phần việc “Dân vận khéo”","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t305","type":"text","x":60,"y":507,"w":58,"rotation":0,"content":"STT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.42},{"id":"t306","type":"text","x":128,"y":507,"w":152,"rotation":0,"content":"Tên mô hình/\nphần việc","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t307","type":"text","x":290,"y":507,"w":123,"rotation":0,"content":"Địa bàn, đối tượng","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t308","type":"text","x":423,"y":507,"w":167,"rotation":0,"content":"Kết quả cụ thể đến 30/6/2026","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t309","type":"text","x":600,"y":507,"w":140,"rotation":0,"content":"Nhiệm vụ/đề xuất 6 tháng cuối năm","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t310","type":"text","x":60,"y":591,"w":58,"rotation":0,"content":"1","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t311","type":"text","x":128,"y":591,"w":152,"rotation":0,"content":"“Alo - Đoàn kết vì Yên Nghĩa hôm nay” (Ủy ban MTTQ Việt Nam phường chủ trì)","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t312","type":"text","x":290,"y":591,"w":123,"rotation":0,"content":"Toàn phường; cán bộ, đoàn viên, hội viên và Nhân dân","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t313","type":"text","x":423,"y":591,"w":167,"rotation":0,"content":"Ban hành 05 văn bản quản lý, vận hành và bộ tiêu chí đánh giá; đăng tải 185 tin, bài, ảnh, video; 320.000 lượt tiếp cận; 28.000 lượt tương tác; tiếp nhận 68 phản ánh, chuyển xử lý 68/68, giải quyết dứt điểm 60 vụ việc (88,2%)","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t314","type":"text","x":600,"y":591,"w":140,"rotation":0,"content":"Duy trì đăng tải 05 - 07 tin, bài/tuần; mỗi tháng 03 video tuyên truyền; phản hồi phản ánh của Nhân dân trong 24 - 48 giờ; nâng số người theo dõi lên trên 5.000","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42}]'),
