:false,"align":"left","lineHeight":1.42},{"id":"t373","type":"text","x":423,"y":180,"w":167,"rotation":0,"content":"Duy trì hoạt động thường xuyên, tạo nguồn quỹ hỗ trợ hội viên và trẻ em có hoàn cảnh khó khăn (do mô hình mới được triển khai từ tháng 4 năm 2026, gần sát thời điểm địa phương chuẩn bị thực hiện sắp xếp, kiện toàn tổ dân phố nên một số Chi hội trưởng có tâm lý dao động, ảnh hưởng đến tiến độ và hiệu quả triển khai ở một số Chi hội).","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t374","type":"text","x":600,"y":180,"w":140,"rotation":0,"content":"Duy trì và nhân rộng tại 15 tổ dân phố sau sắp xếp","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t375","type":"text","x":60,"y":681,"w":58,"rotation":0,"content":"5","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t376","type":"text","x":128,"y":681,"w":152,"rotation":0,"content":"“Đến từng ngõ, gõ từng nhà - Phụ nữ Yên Nghĩa đồng hành cùng dự án Quốc lộ 6” (Hội LHPN phường)","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t377","type":"text","x":290,"y":681,"w":123,"rotation":0,"content":"Hội viên phụ nữ và hộ dân trong diện giải phóng mặt bằng","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t378","type":"text","x":423,"y":681,"w":167,"rotation":0,"content":"Vận động hội viên gương mẫu chấp hành và tuyên truyền, thuyết phục các hộ dân đồng thuận bàn giao mặt bằng","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t379","type":"text","x":600,"y":681,"w":140,"rotation":0,"content":"Tiếp tục duy trì đến khi hoàn thành công tác giải phóng mặt bằng dự án","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42}]'),
  (32, '#ffffff', '/tin/bg-trang.webp', '[{"id":"s236","type":"shape","x":54,"y":90,"w":70,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s237","type":"shape","x":122,"y":90,"w":164,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s238","type":"shape","x":284,"y":90,"w":135,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s239","type":"shape","x":417,"y":90,"w":179,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s240","type":"shape","x":594,"y":90,"w":152,"h":84,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s276","type":"shape","x":54,"y":174,"w":70,"h":144,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s277","type":"shape","x":122,"y":174,"w":164,"h":144,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s278","type":"shape","x":284,"y":174,"w":135,"h":144,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s279","type":"shape","x":417,"y":174,"w":179,"h":144,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s280","type":"shape","x":594,"y":174,"w":152,"h":144,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s325","type":"shape","x":54,"y":318,"w":70,"h":195,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s326","type":"shape","x":122,"y":318,"w":164,"h":195,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s327","type":"shape","x":284,"y":318,"w":135,"h":195,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s328","type":"shape","x":417,"y":318,"w":179,"h":195,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s329","type":"shape","x":594,"y":318,"w":152,"h":195,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"t380","type":"text","x":60,"y":96,"w":58,"rotation":0,"content":"STT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.42},{"id":"t381","type":"text","x":128,"y":96,"w":152,"rotation":0,"content":"Tên mô hình/\nphần việc","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t382","type":"text","x":290,"y":96,"w":123,"rotation":0,"content":"Địa bàn, đối tượng","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t383","type":"text","x":423,"y":96,"w":167,"rotation":0,"content":"Kết quả cụ thể đến 30/6/2026","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t384","type":"text","x":600,"y":96,"w":140,"rotation":0,"content":"Nhiệm vụ/đề xuất 6 tháng cuối năm","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t385","type":"text","x":60,"y":180,"w":58,"rotation":0,"content":"6","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t386","type":"text","x":128,"y":180,"w":152,"rotation":0,"content":"“Mẹ đỡ đầu” (Hội LHPN phường)","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t387","type":"text","x":290,"y":180,"w":123,"rotation":0,"content":"Trẻ mồ côi, có hoàn cảnh khó khăn trên địa bàn","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t388","type":"text","x":423,"y":180,"w":167,"rotation":0,"content":"Hỗ trợ 02 cháu mồ côi có hoàn cảnh khó khăn với mức 1.000.000 đồng/cháu/tháng","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t389","type":"text","x":600,"y":180,"w":140,"rotation":0,"content":"Duy trì hỗ trợ; vận động thêm nguồn lực xã hội hóa để mở rộng đối tượng","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t390","type":"text","x":60,"y":324,"w":58,"rotation":0,"content":"7","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t391","type":"text","x":128,"y":324,"w":152,"rotation":0,"content":"“Em nuôi của Đoàn” (Đoàn TNCS Hồ Chí Minh phường)","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t392","type":"text","x":290,"y":324,"w":123,"rotation":0,"content":"Thiếu nhi có hoàn cảnh khó khăn trên địa bàn","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t393","type":"text","x":423,"y":324,"w":167,"rotation":0,"content":"Trao quà, hỗ trợ các em nhân dịp kỷ niệm 95 năm Ngày thành lập Đoàn TNCS Hồ Chí Minh","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t394","type":"text","x":600,"y":324,"w":140,"rotation":0,"content":"Duy trì, mở rộng đối tượng gắn với chiến dịch hè thanh niên tình nguyện và chương trình tiếp sức mùa thi","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t395","type":"text","x":60,"y":519,"w":680,"rotation":0,"content":"III. ĐÁNH GIÁ CHUNG","fontSize":27,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.3},{"id":"t396","type":"text","x":60,"y":566,"w":680,"rotation":0,"content":"1. Kết quả nổi bật","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t397","type":"text","x":60,"y":608,"w":680,"rotation":0,"content":"- Công tác Mặt trận và các tổ chức chính trị - xã hội 6 tháng đầu năm 2026 đạt kết quả khá toàn diện, bám sát sự lãnh đạo của Đảng ủy, triển khai nhiệm vụ đồng bộ, hiệu quả; khối đại đoàn kết toàn dân tộc tiếp tục được củng cố vững chắc.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t398","type":"text","x":60,"y":752,"w":680,"rotation":0,"content":"- Cuộc bầu cử đại biểu Quốc hội khóa XVI và đại biểu HĐND các cấp nhiệm kỳ 2026 - 2031 được tổ chức thành công, tuyệt đối an toàn, đúng pháp luật, tỷ lệ cử tri đi bầu đạt trên 98%; tập thể và nhiều cá nhân được UBND Thành phố, Ủy ban MTTQ Việt Nam Thành phố và UBND phường khen thưởng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (33, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t166","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Công tác an sinh xã hội, chăm lo Tết cho người có công, hộ nghèo, hộ có hoàn cảnh khó khăn, trẻ em khuyết tật và người yếu thế thu hút đông đảo nhà hảo tâm, đơn vị đồng hành, lan tỏa truyền thống “lá lành đùm lá rách”, bảo đảm không để ai bị bỏ lại phía sau.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t167","type":"text","x":60,"y":240,"w":680,"rotation":0,"content":"- Hoạt động giám sát, phản biện xã hội và tham gia xây dựng Đảng, xây dựng chính quyền từng bước đi vào nền nếp; nhiều kiến nghị sau giám sát được cấp ủy, chính quyền tiếp thu, giải quyết.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t168","type":"text","x":60,"y":350,"w":680,"rotation":0,"content":"- Chuyển đổi số trong công tác Mặt trận có chuyển biến rõ nét: mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay” được vận hành bài bản, có quy chế, quy trình và bộ tiêu chí đánh giá; tỷ lệ giải quyết phản ánh, kiến nghị của Nhân dân đạt 96,2%, tạo được niềm tin và sự đồng thuận trong Nhân dân.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t169","type":"text","x":60,"y":494,"w":680,"rotation":0,"content":"- Việc triển khai đồng bộ các chủ trương lớn của Trung ương, Thành phố, nhất là Nghị quyết số 02-NQ/TW của Bộ Chính trị về xây dựng và phát triển Thủ đô Hà Nội trong kỷ nguyên mới và Nghị quyết số 57-NQ/TW về phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia đã tạo động lực đổi mới phương thức hoạt động của hệ thống Mặt trận và các tổ chức chính trị - xã hội. Công tác tuyên truyền, vận động ngày càng được đổi mới theo hướng gần dân, sát cơ sở, ứng dụng mạnh mẽ công nghệ số; phát huy hiệu quả vai trò tập hợp, đoàn kết Nhân dân, góp phần củng cố niềm tin của Nhân dân đối với sự lãnh đạo của Đảng, sự quản lý, điều hành của chính quyền và tăng cường khối đại đoàn kết toàn dân tộc trong thực hiện các nhiệm vụ phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh trên địa bàn.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (34, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t170","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"2. Tồn tại, hạn chế và nguyên nhân","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t171","type":"text","x":60,"y":138,"w":680,"rotation":0,"content":"2.1. Tồn tại, hạn chế","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t172","type":"text","x":60,"y":177,"w":680,"rotation":0,"content":"- Ban Thanh tra nhân dân phường chưa ban hành Kế hoạch hoạt động kiểm tra, giám sát năm 2026, làm ảnh hưởng đến tính chủ động và tiến độ triển khai hoạt động giám sát của Ban.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t173","type":"text","x":60,"y":287,"w":680,"rotation":0,"content":"- Công tác tuyên truyền ở một số tổ dân phố chưa thật sự đồng đều; việc ứng dụng nền tảng số, đổi mới hình thức truyền thông chưa phát huy hết hiệu quả, mức độ tương tác và khả năng lan tỏa tại cơ sở còn hạn chế; chất lượng tin, bài, hình ảnh, video chưa đồng đều.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t174","type":"text","x":60,"y":431,"w":680,"rotation":0,"content":"- Công tác nắm bắt dư luận xã hội, phản ánh tâm tư, nguyện vọng của Nhân dân ở một số thời điểm chưa thật kịp thời; việc trả lời, phản hồi một số phản ánh còn chậm, vẫn còn phản ánh, kiến nghị chưa được giải quyết dứt điểm.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t175","type":"text","x":60,"y":541,"w":680,"rotation":0,"content":"- Tỷ lệ tham gia hoạt động cộng đồng tại một số khu chung cư còn hạn chế; cơ sở vật chất phục vụ sinh hoạt cộng đồng còn thiếu, nhất là tại các tổ dân phố sau sáp nhập.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t176","type":"text","x":60,"y":651,"w":680,"rotation":0,"content":"- Một số mô hình “Dân vận khéo” của các tổ chức thành viên chưa lượng hóa được kết quả, chưa có tiêu chí đánh giá và chế độ báo cáo định kỳ.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t177","type":"text","x":60,"y":727,"w":680,"rotation":0,"content":"2.2. Nguyên nhân","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":true,"align":"left","lineHeight":1.4},{"id":"t178","type":"text","x":60,"y":766,"w":680,"rotation":0,"content":"- Nguyên nhân khách quan: khối lượng công việc 6 tháng đầu năm rất lớn, tập trung cao độ cho công tác bầu cử và việc sắp xếp đơn vị hành chính, sáp nhập tổ dân phố; việc xử lý, trả lời phản ánh của Nhân dân phụ thuộc tiến độ giải quyết của các cơ quan chuyên môn;","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (35, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t179","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"kinh phí hoạt động cho MTTQ và các đoàn thể chính trị - xã hội chưa đáp ứng yêu cầu nhiệm vụ.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t180","type":"text","x":60,"y":172,"w":680,"rotation":0,"content":"- Nguyên nhân chủ quan: công tác tham mưu, đôn đốc của một số bộ phận có lúc chưa quyết liệt; một số tổ chức thành viên chưa chủ động trong cung cấp tin, bài và triển khai mô hình đã đăng ký; kỹ năng ứng dụng công nghệ thông tin của một bộ phận cán bộ Mặt trận ở khu dân cư còn hạn chế; việc theo dõi, đánh giá kết quả các mô hình chưa được thực hiện thường xuyên.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t181","type":"text","x":60,"y":350,"w":680,"rotation":0,"content":"IV. NHIỆM VỤ, GIẢI PHÁP TRỌNG TÂM 6 THÁNG CUỐI NĂM 2026","fontSize":27,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.3},{"id":"t182","type":"text","x":60,"y":432,"w":680,"rotation":0,"content":"1. Kiện toàn tổ chức bộ máy Mặt trận và các đoàn thể sau sắp xếp tổ dân phố","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t183","type":"text","x":60,"y":507,"w":680,"rotation":0,"content":"Tập trung hướng dẫn, chỉ đạo kiện toàn Ban Công tác Mặt trận, các chi hội, chi đoàn tại 15 tổ dân phố; kiện toàn Ban Thanh tra nhân dân và Ban Giám sát đầu tư của cộng đồng theo quy định của Luật Thực hiện dân chủ ở cơ sở và Nghị định số 59/2023/NĐ-CP; tiếp tục thực hiện Đề án sắp xếp, tinh gọn các hội quần chúng; nâng cao chất lượng đào tạo, bồi dưỡng cán bộ Mặt trận ở cơ sở, chú trọng kỹ năng ứng dụng công nghệ thông tin.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t184","type":"text","x":60,"y":730,"w":680,"rotation":0,"content":"2. Nâng cao chất lượng công tác giám sát, phản biện xã hội, tham gia xây dựng Đảng, xây dựng chính quyền","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t185","type":"text","x":60,"y":805,"w":680,"rotation":0,"content":"Chỉ đạo Ban Thanh tra nhân dân ban hành Kế hoạch hoạt động kiểm tra, giám sát năm 2026 trong tháng 7/2026 và tổ chức cuộc giám sát chuyên đề đầu tiên trong Quý III/2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (36, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t186","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Thực hiện tốt hoạt động giám sát theo Quyết định số 217-QĐ/TW, Quyết định số 218-QĐ/TW của Bộ Chính trị và Chỉ thị số 18-CT/TW ngày 26/10/2022 của Ban Bí thư; tập trung giám sát công tác tiếp công dân, tiếp xúc đối thoại của người đứng đầu cấp ủy, chính quyền; giải quyết khiếu nại, tố cáo kéo dài, phức tạp theo Chỉ thị số 15 của Thành ủy; việc thực hiện Hướng dẫn số 30/HD-MTTQ-BTT ngày 28/10/2021 và Luật Thực hiện dân chủ ở cơ sở. Tổ chức góp ý, phản biện xã hội đối với dự thảo các văn bản của Đảng ủy, HĐND, UBND phường; phối hợp tổ chức tiếp xúc cử tri trước và sau các kỳ họp; xây dựng Thông báo của MTTQ tham gia xây dựng chính quyền 6 tháng cuối năm 2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t187","type":"text","x":60,"y":460,"w":680,"rotation":0,"content":"3. Duy trì, nâng cao hiệu quả phong trào “Dân vận khéo” gắn với chuyển đổi số","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t188","type":"text","x":60,"y":535,"w":680,"rotation":0,"content":"Tiếp tục phát huy mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay” theo các chỉ tiêu cụ thể đã đề ra; vận hành có hiệu quả các ứng dụng, phần mềm Thành phố đang triển khai, đặc biệt là ứng dụng HanoiWork và hệ thống “Mặt trận số”; từng bước triển khai chuyển đổi số tại Ban Công tác Mặt trận các tổ dân phố. Yêu cầu mỗi tổ chức chính trị - xã hội đăng ký và báo cáo kết quả ít nhất 01 mô hình “Dân vận khéo” có sản phẩm cụ thể trước ngày 31/12/2026.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t189","type":"text","x":60,"y":793,"w":680,"rotation":0,"content":"4. Đổi mới, nâng cao chất lượng các cuộc vận động, phong trào thi đua yêu nước và công tác an sinh xã hội","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35}]'),
  (37, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t190","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Tiếp tục thực hiện Cuộc vận động “Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh”, “Người Việt Nam ưu tiên dùng hàng Việt Nam” và phong trào “Sáng - Xanh - Sạch - Đẹp”; phối hợp tham gia giải quyết 05 “điểm nghẽn” của Thành phố. Tăng cường vận động Quỹ “Vì người nghèo”, triển khai Tháng cao điểm “Vì người nghèo”; tổ chức tốt Ngày hội Đại đoàn kết toàn dân tộc và các hoạt động kỷ niệm 96 năm Ngày truyền thống MTTQ Việt Nam; chuẩn bị sớm nguồn lực cho các chương trình an sinh xã hội, thăm hỏi, tặng quà nhân dịp các ngày lễ lớn cuối năm và Tết Nguyên đán.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t191","type":"text","x":60,"y":390,"w":680,"rotation":0,"content":"5. Đẩy mạnh công tác tuyên truyền, vận động, nắm tình hình Nhân dân","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t192","type":"text","x":60,"y":465,"w":680,"rotation":0,"content":"Tuyên truyền các nghị quyết của Đảng, đặc biệt là Nghị quyết Đại hội XIV của Đảng, Nghị quyết Đại hội Đảng bộ thành phố Hà Nội lần thứ XVIII, Luật Thủ đô và các nhiệm vụ phát triển kinh tế - xã hội của Thủ đô; tuyên truyền kỷ niệm 79 năm Ngày Thương binh - Liệt sĩ (27/7/1947 - 27/7/2026), 81 năm Cách mạng tháng Tám thành công (19/8/1945 - 19/8/2026) và Quốc khánh nước Cộng hòa xã hội chủ nghĩa Việt Nam (02/9/1945 - 02/9/2026); đôn đốc, giám sát việc thực hiện Chỉ thị số 05-CT/TW, Kết luận số 01-KL/TW của Bộ Chính trị. Tiếp tục bám sát địa bàn, nắm chắc tình hình Nhân dân, nhất là các hộ dân trong diện giải phóng mặt bằng dự án Vành đai 4, Quốc lộ 6 và đường Đê tả Đáy; kịp thời phản ánh, phối hợp xử lý các vấn đề phát sinh, không để hình thành “điểm nóng”.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t193","type":"text","x":60,"y":864,"w":680,"rotation":0,"content":"Biểu nhiệm vụ trọng tâm 6 tháng cuối năm 2026","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6}]'),
  (38, '#ffffff', '/tin/bg-trang.webp', '[{"id":"s241","type":"shape","x":54,"y":90,"w":66,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s242","type":"shape","x":118,"y":90,"w":211,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s243","type":"shape","x":327,"y":90,"w":178,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s244","type":"shape","x":503,"y":90,"w":117,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s245","type":"shape","x":618,"y":90,"w":127,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s281","type":"shape","x":54,"y":150,"w":66,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s282","type":"shape","x":118,"y":150,"w":211,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s283","type":"shape","x":327,"y":150,"w":178,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s284","type":"shape","x":503,"y":150,"w":117,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s285","type":"shape","x":618,"y":150,"w":127,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s330","type":"shape","x":54,"y":421,"w":66,"h":220,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s331","type":"shape","x":118,"y":421,"w":211,"h":220,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s332","type":"shape","x":327,"y":421,"w":178,"h":220,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s333","type":"shape","x":503,"y":421,"w":117,"h":220,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s334","type":"shape","x":618,"y":421,"w":127,"h":220,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s416","type":"shape","x":54,"y":641,"w":66,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s417","type":"shape","x":118,"y":641,"w":211,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s418","type":"shape","x":327,"y":641,"w":178,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s419","type":"shape","x":503,"y":641,"w":117,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s420","type":"shape","x":618,"y":641,"w":127,"h":271,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"t431","type":"text","x":60,"y":96,"w":54,"rotation":0,"content":"STT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.42},{"id":"t432","type":"text","x":124,"y":96,"w":199,"rotation":0,"content":"Nhiệm vụ/phần việc\ntrọng tâm","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t433","type":"text","x":333,"y":96,"w":166,"rotation":0,"content":"Chủ trì, phối hợp","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t434","type":"text","x":509,"y":96,"w":105,"rotation":0,"content":"Thời gian hoàn thành","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t435","type":"text","x":624,"y":96,"w":115,"rotation":0,"content":"Kết quả/\nsản phẩm","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t436","type":"text","x":60,"y":156,"w":54,"rotation":0,"content":"1","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t437","type":"text","x":124,"y":156,"w":199,"rotation":0,"content":"Kiện toàn tổ chức bộ máy Mặt trận và các đoàn thể tại 15 tổ dân phố sau sắp xếp; kiện toàn Ban Thanh tra nhân dân, Ban Giám sát đầu tư của cộng đồng","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t438","type":"text","x":333,"y":156,"w":166,"rotation":0,"content":"Ban Thường trực Ủy ban MTTQ Việt Nam phường chủ trì; phối hợp UBND phường, các chi bộ tổ dân phố","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t439","type":"text","x":509,"y":156,"w":105,"rotation":0,"content":"Quý III/2026","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t440","type":"text","x":624,"y":156,"w":115,"rotation":0,"content":"Quyết định công nhận Ban Công tác Mặt trận, Ban Thanh tra nhân dân, Ban Giám sát đầu tư của cộng\nđồng tại 15 tổ dân phố","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t441","type":"text","x":60,"y":427,"w":54,"rotation":0,"content":"2","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t442","type":"text","x":124,"y":427,"w":199,"rotation":0,"content":"Ban hành và tổ chức thực hiện Kế hoạch hoạt động kiểm tra, giám sát năm 2026 của Ban Thanh tra nhân dân; nâng cao chất lượng giám sát, phản biện xã hội","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t443","type":"text","x":333,"y":427,"w":166,"rotation":0,"content":"Ban Thanh tra nhân dân chủ trì; Ban Thường trực Ủy ban MTTQ Việt Nam phường phê duyệt, chỉ đạo","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t444","type":"text","x":509,"y":427,"w":105,"rotation":0,"content":"Tháng 7/2026; giám sát chuyên đề trong Quý III/2026","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t445","type":"text","x":624,"y":427,"w":115,"rotation":0,"content":"Kế hoạch được ban hành; ít nhất 01 cuộc giám sát chuyên đề và văn bản kiến nghị sau giám sát","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t446","type":"text","x":60,"y":647,"w":54,"rotation":0,"content":"3","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t447","type":"text","x":124,"y":647,"w":199,"rotation":0,"content":"Duy trì, nâng cao hiệu quả mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay” và chuyển đổi số trong hệ thống Mặt trận","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t448","type":"text","x":333,"y":647,"w":166,"rotation":0,"content":"Đồng chí Phó Chủ tịch Ủy ban MTTQ Việt Nam phường phụ trách mô hình chủ trì; phối hợp các tổ chức chính trị - xã hội, các Ban Công tác Mặt trận","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t449","type":"text","x":509,"y":647,"w":105,"rotation":0,"content":"Thường xuyên, báo cáo kết quả tháng 12/2026","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t450","type":"text","x":624,"y":647,"w":115,"rotation":0,"content":"05 - 07 tin, bài/tuần; 03 video/tháng; trên 5.000 người theo dõi; tỷ lệ phản hồi phản ánh trong 24 - 48 giờ đạt trên 90%","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42}]'),
  (39, '#ffffff', '/tin/bg-trang.webp', '[{"id":"s246","type":"shape","x":54,"y":90,"w":66,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s247","type":"shape","x":118,"y":90,"w":211,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s248","type":"shape","x":327,"y":90,"w":178,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s249","type":"shape","x":503,"y":90,"w":117,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s250","type":"shape","x":618,"y":90,"w":127,"h":60,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s286","type":"shape","x":54,"y":150,"w":66,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s287","type":"shape","x":118,"y":150,"w":211,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s288","type":"shape","x":327,"y":150,"w":178,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s289","type":"shape","x":503,"y":150,"w":117,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s290","type":"shape","x":618,"y":150,"w":127,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s335","type":"shape","x":54,"y":473,"w":66,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s336","type":"shape","x":118,"y":473,"w":211,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s337","type":"shape","x":327,"y":473,"w":178,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s338","type":"shape","x":503,"y":473,"w":117,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"s339","type":"shape","x":618,"y":473,"w":127,"h":323,"rotation":0,"borderWidth":1,"borderColor":"#9aa7b4","radius":0,"opacity":1},{"id":"t399","type":"text","x":60,"y":96,"w":54,"rotation":0,"content":"STT","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"center","lineHeight":1.42},{"id":"t400","type":"text","x":124,"y":96,"w":199,"rotation":0,"content":"Nhiệm vụ/phần việc\ntrọng tâm","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t401","type":"text","x":333,"y":96,"w":166,"rotation":0,"content":"Chủ trì, phối hợp","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t402","type":"text","x":509,"y":96,"w":105,"rotation":0,"content":"Thời gian hoàn thành","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t403","type":"text","x":624,"y":96,"w":115,"rotation":0,"content":"Kết quả/\nsản phẩm","fontSize":17,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.42},{"id":"t404","type":"text","x":60,"y":156,"w":54,"rotation":0,"content":"4","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t405","type":"text","x":124,"y":156,"w":199,"rotation":0,"content":"Tổ chức tốt Ngày hội Đại đoàn kết toàn dân tộc, kỷ niệm 96 năm Ngày truyền thống MTTQ Việt Nam và Tháng cao điểm “Vì người nghèo”","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t406","type":"text","x":333,"y":156,"w":166,"rotation":0,"content":"Ban Thường trực Ủy ban MTTQ Việt Nam phường chủ trì; phối hợp UBND phường và các Ban Công tác Mặt trận","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t407","type":"text","x":509,"y":156,"w":105,"rotation":0,"content":"Tháng 10 - 11/2026","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t408","type":"text","x":624,"y":156,"w":115,"rotation":0,"content":"100% tổ dân phố tổ chức Ngày hội; hoàn thành chỉ tiêu vận động Quỹ “Vì người nghèo”; hộ nghèo, cận nghèo, đối tượng yếu thế được hỗ trợ kịp thời","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t409","type":"text","x":60,"y":479,"w":54,"rotation":0,"content":"5","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"center","lineHeight":1.42},{"id":"t410","type":"text","x":124,"y":479,"w":199,"rotation":0,"content":"Tuyên truyền các nghị quyết của Đảng, các ngày lễ lớn; tiếp tục tham gia tuyên truyền, vận động giải phóng mặt bằng các dự án trọng điểm và giải quyết “05 điểm nghẽn”","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t411","type":"text","x":333,"y":479,"w":166,"rotation":0,"content":"Ban Thường trực Ủy ban MTTQ Việt Nam phường và các tổ chức chính trị - xã hội chủ trì; phối hợp UBND phường, Công an phường","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t412","type":"text","x":509,"y":479,"w":105,"rotation":0,"content":"Thường xuyên trong 6 tháng cuối năm 2026","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t413","type":"text","x":624,"y":479,"w":115,"rotation":0,"content":"Các đợt tuyên truyền, ra quân được tổ chức theo kế hoạch; tỷ lệ hộ dân đồng thuận bàn giao mặt bằng tăng; không phát sinh “điểm nóng”","fontSize":18,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":false,"italic":false,"align":"left","lineHeight":1.42},{"id":"t414","type":"text","x":60,"y":802,"w":680,"rotation":0,"content":"V. KIẾN NGHỊ, ĐỀ XUẤT","fontSize":27,"fontFamily":"\"Times New Roman\", Times, serif","color":"#a20f1a","bold":true,"italic":false,"align":"left","lineHeight":1.3},{"id":"t415","type":"text","x":60,"y":849,"w":680,"rotation":0,"content":"1. Đề nghị Ban Thường vụ, Thường trực Đảng ủy phường","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35}]'),
  (40, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t194","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"- Cho chủ trương và chỉ đạo các chi bộ tổ dân phố phối hợp với Ban Thường trực Ủy ban MTTQ Việt Nam phường hoàn thành việc kiện toàn Ban Công tác Mặt trận, các chi hội, chi đoàn tại 15 tổ dân phố trong Quý III/2026; đồng thời cho ý kiến về việc bố trí, sử dụng đội ngũ cán bộ Mặt trận, chi hội đoàn thể dôi dư sau sắp xếp.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t195","type":"text","x":60,"y":274,"w":680,"rotation":0,"content":"- Định hướng nội dung giám sát chuyên đề năm 2026 của Ban Thanh tra nhân dân và Ủy ban MTTQ Việt Nam phường, trọng tâm là công tác quản lý đất đai, trật tự xây dựng, vệ sinh môi trường tại khu vực chịu ảnh hưởng của các dự án Vành đai 4 và Quốc lộ 6.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t196","type":"text","x":60,"y":418,"w":680,"rotation":0,"content":"- Chỉ đạo đưa nội dung phong trào thi đua “Dân vận khéo” và kết quả xử lý phản ánh của Nhân dân qua nền tảng số vào tiêu chí đánh giá, xếp loại tổ chức đảng và đảng viên hằng năm.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t197","type":"text","x":60,"y":528,"w":680,"rotation":0,"content":"- Quan tâm xem xét, báo cáo cấp có thẩm quyền bổ sung 01 đồng chí Phó Chủ tịch Thường trực Ủy ban MTTQ Việt Nam phường hoạt động chuyên trách để đáp ứng yêu cầu nhiệm vụ trong giai đoạn hiện nay. Thực tế, các đồng chí Phó Chủ tịch Ủy ban MTTQ Việt Nam phường hiện đều đồng thời là người đứng đầu các tổ chức chính trị - xã hội của phường, thực hiện nhiệm vụ theo chế độ kiêm nhiệm. Trong khi đó, sau khi thực hiện mô hình chính quyền địa phương hai cấp, sắp xếp đơn vị hành chính, tổ chức lại tổ dân phố và mở rộng phạm vi quản lý, khối lượng công việc của Ủy ban MTTQ Việt Nam phường tăng lên rõ rệt;","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (41, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t198","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"nhiều nhiệm vụ mới được giao như chuyển đổi số, giám sát, phản biện xã hội, tiếp nhận và xử lý phản ánh của Nhân dân trên môi trường số, tham gia giải quyết các nhiệm vụ chính trị trọng tâm, các dự án trọng điểm và công tác an sinh xã hội. Việc bố trí 01 đồng chí Phó Chủ tịch Thường trực chuyên trách sẽ tăng cường năng lực tham mưu, điều hành, bảo đảm tính thường xuyên, liên tục trong hoạt động của Ủy ban MTTQ Việt Nam phường; đồng thời tạo điều kiện để các đồng chí là người đứng đầu các tổ chức chính trị - xã hội tập trung thực hiện tốt chức năng, nhiệm vụ của tổ chức mình, góp phần nâng cao hiệu quả hoạt động của cả hệ thống Mặt trận và các tổ chức chính trị - xã hội ở cơ sở.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t199","type":"text","x":60,"y":445,"w":680,"rotation":0,"content":"2. Đề nghị UBND phường và các cơ quan, đơn vị liên quan","fontSize":24,"fontFamily":"\"Times New Roman\", Times, serif","color":"#0b3f8f","bold":true,"italic":false,"align":"left","lineHeight":1.35},{"id":"t200","type":"text","x":60,"y":487,"w":680,"rotation":0,"content":"- Chỉ đạo các bộ phận chuyên môn xác định rõ thời hạn trả lời các phản ánh, kiến nghị của Nhân dân tiếp nhận qua Trang Fanpage và mô hình “Alo - Đoàn kết vì Yên Nghĩa hôm nay”, bảo đảm phản hồi trong thời gian từ 24 đến 48 giờ; chỉ đạo giải quyết dứt điểm các phản ánh, kiến nghị còn tồn đọng.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t201","type":"text","x":60,"y":665,"w":680,"rotation":0,"content":"- Bố trí kinh phí hoạt động cho Ủy ban MTTQ Việt Nam phường và các tổ chức chính trị - xã hội, trong đó có kinh phí duy trì hoạt động của Trang Fanpage và các mô hình “Dân vận khéo”.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55},{"id":"t202","type":"text","x":60,"y":775,"w":680,"rotation":0,"content":"- Quan tâm bố trí, nâng cấp cơ sở vật chất phục vụ sinh hoạt cộng đồng tại các tổ dân phố sau sáp nhập; tổ chức tập huấn kỹ năng ứng dụng công nghệ thông tin cho đội ngũ cán bộ Mặt trận, đoàn thể ở khu dân cư.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.55}]'),
  (42, '#ffffff', '/tin/bg-trang.webp', '[{"id":"t203","type":"text","x":60,"y":96,"w":680,"rotation":0,"content":"Trên đây là báo cáo kết quả công tác Mặt trận, các tổ chức chính trị - xã hội 6 tháng đầu năm, phong trào “Dân vận khéo” và nhiệm vụ trọng tâm 6 tháng cuối năm 2026 của Ban Thường trực Ủy ban MTTQ Việt Nam phường Yên Nghĩa; kính báo cáo Ban Thường vụ Đảng ủy phường./.","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":false,"italic":false,"align":"justify","lineHeight":1.6},{"id":"t204","type":"text","x":60,"y":249,"w":680,"rotation":0,"content":"Nơi nhận:","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":true,"italic":false,"align":"left","lineHeight":1.5},{"id":"t205","type":"text","x":60,"y":282,"w":680,"rotation":0,"content":"- BTT UB MTTQ Việt Nam Thành phố (để b/c);","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.5},{"id":"t206","type":"text","x":60,"y":315,"w":680,"rotation":0,"content":"- Ban Thường vụ Đảng ủy phường (để b/c);","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.5},{"id":"t207","type":"text","x":60,"y":348,"w":680,"rotation":0,"content":"- Các tổ chức chính trị - xã hội phường;","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.5},{"id":"t208","type":"text","x":60,"y":381,"w":680,"rotation":0,"content":"- Lưu: BTT-MTTQ.","fontSize":19,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#6b7280","bold":false,"italic":true,"align":"left","lineHeight":1.5},{"id":"t209","type":"text","x":400,"y":414,"w":340,"rotation":0,"content":"TM. BAN THƯỜNG TRỰC\nCHỦ TỊCH","fontSize":20,"fontFamily":"\"Segoe UI\", system-ui, sans-serif","color":"#22303f","bold":true,"italic":false,"align":"center","lineHeight":1.5},{"id":"t210","type":"text","x":400,"y":550,"w":340,"rotation":0,"content":"Lương Huệ Minh","fontSize":22,"fontFamily":"\"Times New Roman\", Times, serif","color":"#22303f","bold":true,"italic":false,"align":"center","lineHeight":1.4}]'),
